{
  "name": "ghanifoods-backend",
  "version": "0.1.0",
  "private": true,
  "main": "dist/index.js",
  "scripts": {
    "dev": "tsx watch src/index.ts",
    "build": "tsc -p tsconfig.json",
    "start": "node dist/index.js"
  },
  "dependencies": {
    "cors": "^2.8.5",
    "express": "^4.19.2"
  },
  "devDependencies": {
    "@types/cors": "^2.8.17",
    "@types/express": "^4.17.21",
    "@types/node": "^22.7.5",
    "tsx": "^4.19.2",
    "typescript": "^5.6.3"
  }
}

// src/data.ts
// In-memory mock data for local/dev use - mirrors apps/frontend/lib/mock-data/*
// Replace with real DB (Prisma/Postgres etc.) later without changing route shapes.

export type RawMaterial = {
  id: string; name: string; unit: string;
  quantityInStock: number; avgUnitCost: number; lowStockThreshold: number;
};
export let rawMaterials: RawMaterial[] = [
  { id: "rm-1", name: "Atta (Flour)", unit: "kg", quantityInStock: 420, avgUnitCost: 145.5, lowStockThreshold: 100 },
  { id: "rm-2", name: "Ghee", unit: "kg", quantityInStock: 65, avgUnitCost: 780, lowStockThreshold: 80 },
  { id: "rm-3", name: "Salt", unit: "kg", quantityInStock: 210, avgUnitCost: 28, lowStockThreshold: 50 },
  { id: "rm-4", name: "Spice Mix", unit: "kg", quantityInStock: 34, avgUnitCost: 620, lowStockThreshold: 40 },
];

export type PackagingMaterial = {
  id: string; name: string; unitCost: number; stockQty: number; lowStockThreshold: number;
};
export let packagingMaterials: PackagingMaterial[] = [
  { id: "pm-1", name: "Carton Box (Large)", unitCost: 45, stockQty: 320, lowStockThreshold: 100 },
  { id: "pm-2", name: "Shopper Bag", unitCost: 3.5, stockQty: 2400, lowStockThreshold: 500 },
  { id: "pm-3", name: "Dabbe (Tin)", unitCost: 22, stockQty: 150, lowStockThreshold: 60 },
];

export type ProductionBatch = {
  id: string; batchDate: string; outputYieldKg: number; wastageKg: number;
  leftoverQtyKg: number; bulkCostPerKg: number; status: "in_progress" | "completed";
};
export let productionBatches: ProductionBatch[] = [
  { id: "batch-1", batchDate: "2026-08-10", outputYieldKg: 500, wastageKg: 8, leftoverQtyKg: 40, bulkCostPerKg: 210.75, status: "completed" },
  { id: "batch-2", batchDate: "2026-08-13", outputYieldKg: 480, wastageKg: 5, leftoverQtyKg: 480, bulkCostPerKg: 205.3, status: "completed" },
  { id: "batch-3", batchDate: "2026-08-16", outputYieldKg: 300, wastageKg: 0, leftoverQtyKg: 0, bulkCostPerKg: 0, status: "in_progress" },
];

export type FinishedCarton = {
  id: string; name: string; sourceBatchId: string;
  packetsPerCarton: number; costPerCarton: number; stockQty: number;
};
export let finishedCartons: FinishedCarton[] = [
  { id: "fc-1", name: "Nimko Carton - 24pk", sourceBatchId: "batch-1", packetsPerCarton: 24, costPerCarton: 610, stockQty: 85 },
  { id: "fc-2", name: "Nimko Carton - 48pk", sourceBatchId: "batch-2", packetsPerCarton: 48, costPerCarton: 1150, stockQty: 42 },
];

export type Customer = { id: string; name: string; phone: string; currentBalance: number; };
export let customers: Customer[] = [
  { id: "cust-1", name: "Al-Madina General Store", phone: "0300-1234567", currentBalance: 12500 },
  { id: "cust-2", name: "Bilal Traders", phone: "0333-9988776", currentBalance: -2000 },
  { id: "cust-3", name: "Rehman Wholesale", phone: "0345-1122334", currentBalance: 0 },
];

export type Invoice = {
  id: string; customerId: string; customerName: string;
  invoiceDate: string; totalAmount: number; status: "unpaid" | "partial" | "paid";
};
export let invoices: Invoice[] = [
  { id: "inv-1001", customerId: "cust-1", customerName: "Al-Madina General Store", invoiceDate: "2026-08-15", totalAmount: 18300, status: "partial" },
  { id: "inv-1002", customerId: "cust-2", customerName: "Bilal Traders", invoiceDate: "2026-08-14", totalAmount: 9200, status: "paid" },
  { id: "inv-1003", customerId: "cust-3", customerName: "Rehman Wholesale", invoiceDate: "2026-08-12", totalAmount: 4600, status: "unpaid" },
];

export type Payment = {
  id: string; customerId: string; customerName: string;
  amount: number; note: string; paidAt: string;
};
export let payments: Payment[] = [
  { id: "pay-1", customerId: "cust-2", customerName: "Bilal Traders", amount: 9200, note: "Full settlement inv-1002", paidAt: "2026-08-15" },
  { id: "pay-2", customerId: "cust-1", customerName: "Al-Madina General Store", amount: 5800, note: "Partial payment", paidAt: "2026-08-16" },
];

export type CustomerItemPrice = { customerId: string; itemId: string; lastSoldPrice: number; };
export let customerItemPrices: CustomerItemPrice[] = [
  { customerId: "cust-1", itemId: "fc-1", lastSoldPrice: 640 },
  { customerId: "cust-2", itemId: "fc-2", lastSoldPrice: 1180 },
];

export const dashboardKpis = {
  totalRawMaterialValue: 128450,
  batchesThisMonth: 6,
  finishedCartonsReady: 127,
  totalReceivables: 15900,
};

export let settings = {
  businessName: "GhaniFoods",
  address: "Mansehra, Khyber Pakhtunkhwa, Pakistan",
  invoiceFooterText: "Thank you for your business!",
  defaultProfitMarginPercent: 20,
  lowStockThresholdDefault: 50,
};

// src/index.ts
import express from "express";
import cors from "cors";
import * as data from "./data";

const app = express();
const PORT = process.env.PORT ? Number(process.env.PORT) : 4000;
const FRONTEND_ORIGIN = process.env.FRONTEND_ORIGIN || "http://localhost:3000";

app.use(cors({ origin: FRONTEND_ORIGIN }));
app.use(express.json());

app.use((req, _res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

app.get("/api/health", (_req, res) => res.json({ status: "ok" }));

app.get("/api/kpis", (_req, res) => res.json(data.dashboardKpis));

app.get("/api/raw-materials", (_req, res) => res.json(data.rawMaterials));
app.post("/api/raw-materials", (req, res) => {
  const item = { id: `rm-${data.rawMaterials.length + 1}`, ...req.body };
  data.rawMaterials.push(item);
  res.status(201).json(item);
});
app.get("/api/raw-materials/:id", (req, res) => {
  const item = data.rawMaterials.find((m) => m.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.post("/api/raw-materials/:id/receipts", (req, res) => {
  res.status(201).json({ received: true, rawMaterialId: req.params.id, ...req.body });
});

app.get("/api/packaging-materials", (_req, res) => res.json(data.packagingMaterials));
app.post("/api/packaging-materials/:id/restock", (req, res) => {
  res.status(201).json({ restocked: true, materialId: req.params.id, ...req.body });
});

app.get("/api/batches", (_req, res) => res.json(data.productionBatches));
app.get("/api/batches/:id", (req, res) => {
  const item = data.productionBatches.find((b) => b.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.post("/api/batches", (req, res) => {
  const item = { id: `batch-${data.productionBatches.length + 1}`, status: "in_progress", ...req.body };
  data.productionBatches.push(item);
  res.status(201).json(item);
});
app.post("/api/batches/:id/overhead", (req, res) => {
  res.status(200).json({ allocated: true, batchId: req.params.id, ...req.body });
});

app.get("/api/finished-cartons", (_req, res) => res.json(data.finishedCartons));
app.post("/api/finished-cartons/packing-run", (req, res) => {
  res.status(201).json({ packed: true, ...req.body });
});

app.get("/api/customers", (_req, res) => res.json(data.customers));
app.post("/api/customers", (req, res) => {
  const item = { id: `cust-${data.customers.length + 1}`, currentBalance: 0, ...req.body };
  data.customers.push(item);
  res.status(201).json(item);
});
app.get("/api/customers/:id", (req, res) => {
  const item = data.customers.find((c) => c.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.get("/api/customers/:id/item-prices", (req, res) => {
  const rows = data.customerItemPrices.filter((p) => p.customerId === req.params.id);
  res.json(rows);
});

app.get("/api/invoices", (_req, res) => res.json(data.invoices));
app.get("/api/invoices/:id", (req, res) => {
  const item = data.invoices.find((i) => i.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.post("/api/invoices", (req, res) => {
  const item = { id: `inv-${1000 + data.invoices.length + 1}`, status: "unpaid", ...req.body };
  data.invoices.push(item);
  res.status(201).json(item);
});
app.get("/api/invoices/:id/pdf", (req, res) => {
  res.status(200).json({ message: "PDF generation not implemented yet", invoiceId: req.params.id });
});

app.get("/api/payments", (_req, res) => res.json(data.payments));
app.post("/api/payments", (req, res) => {
  const item = { id: `pay-${data.payments.length + 1}`, ...req.body };
  data.payments.push(item);
  res.status(201).json(item);
});

app.get("/api/reports/inventory", (_req, res) => {
  res.json({ rawMaterials: data.rawMaterials, packagingMaterials: data.packagingMaterials });
});
app.get("/api/reports/pnl", (_req, res) => {
  res.json({ batches: data.productionBatches, invoices: data.invoices });
});

app.get("/api/settings", (_req, res) => res.json(data.settings));
app.patch("/api/settings", (req, res) => {
  data.settings = { ...data.settings, ...req.body };
  res.json(data.settings);
});

app.listen(PORT, () => {
  console.log(`GhaniFoods backend running at http://localhost:${PORT}`);
});

"use client";

import React, { useState } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { AtSignIcon, LockIcon } from "lucide-react";
import { GhaniLogo } from "@/components/ui/ghani-logo";
import { AnimatedThemeToggler } from "@/components/ui/animated-theme-toggler";

const LOGIN_IMAGE_URL = "https://res.cloudinary.com/dr9dwesyo/image/upload/v1787001758/ghanifoods/ghani-nimko-bag.png";

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim() || !password.trim()) {
      setError("Please enter both email and password.");
      return;
    }
    setLoading(true);
    setError("");
    document.cookie = "ghanifoods-auth=1; path=/; max-age=86400";
    router.push("/");
  };

  return (
    <main className="relative min-h-screen lg:h-screen lg:overflow-hidden lg:grid lg:grid-cols-2 bg-[var(--background)]">
      {/* Mobile banner (below lg) - compact hero image with logo overlay */}
      <div className="relative h-40 sm:h-48 w-full overflow-hidden lg:hidden">
        <Image
          src={LOGIN_IMAGE_URL}
          alt="Ghani Food - Nimko"
          fill
          priority
          sizes="100vw"
          className="object-cover"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-black/40" />
        <div className="absolute inset-0 flex items-center gap-2 px-5 text-neutral-50">
          <GhaniLogo className="size-6" />
          <p className="text-lg font-semibold">GhaniFoods</p>
        </div>
      </div>

      {/* Theme toggle - top right, clear of the mobile banner and desktop panel */}
      <div className="absolute top-3 right-3 sm:top-4 sm:right-4 z-20">
        <AnimatedThemeToggler className="border border-[var(--surface-border)] bg-[var(--surface)]" />
      </div>

      {/* Desktop split-screen image panel (lg and up only) */}
      <div className="bg-[var(--surface)] relative hidden h-full flex-col border-r border-[var(--surface-border)] lg:flex overflow-hidden">
        <Image
          src={LOGIN_IMAGE_URL}
          alt="Ghani Food - Nimko"
          fill
          priority
          sizes="50vw"
          className="object-cover"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/20 to-black/40" />

        <div className="relative z-10 flex items-center gap-2 text-neutral-50 p-10">
          <GhaniLogo className="size-6" />
          <p className="text-xl font-semibold">GhaniFoods</p>
        </div>

        <div className="relative z-10 mt-auto p-10">
          <blockquote className="space-y-2">
            <p className="text-xl text-neutral-100">
              Real-time visibility into raw materials, batches, and customer
              ledgers - all in one place.
            </p>
            <footer className="font-mono text-sm font-semibold text-neutral-300">
              ~ GhaniFoods Production Team
            </footer>
          </blockquote>
        </div>
      </div>

      {/* Form panel */}
      <div className="relative flex flex-1 lg:min-h-screen flex-col justify-center px-5 py-8 sm:p-8 lg:p-4 bg-[var(--background)]">
        <div className="mx-auto w-full max-w-sm space-y-4">
          <div className="hidden lg:flex items-center gap-2 text-[var(--foreground)]">
            <GhaniLogo className="size-6" />
            <p className="text-xl font-semibold">GhaniFoods</p>
          </div>

          <div className="flex flex-col space-y-1">
            <h1 className="text-xl sm:text-2xl font-bold tracking-wide text-[var(--foreground)]">Sign in to GhaniFoods</h1>
            <p className="text-[var(--text-muted)] text-sm sm:text-base">Enter your credentials to access the dashboard.</p>
          </div>

          <form className="space-y-3" onSubmit={handleSubmit}>
            <div className="relative">
              <input
                type="email"
                placeholder="you@ghanifoods.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full h-11 sm:h-10 rounded-md border border-[var(--surface-border)] bg-[var(--surface)] ps-9 px-3 py-2 text-sm text-[var(--foreground)] placeholder:text-[var(--text-faint)] outline-none focus:border-[var(--surface-border-strong)]"
              />
              <AtSignIcon className="absolute left-3 top-3.5 sm:top-3 size-4 text-[var(--text-faint)] pointer-events-none" />
            </div>

            <div className="relative">
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full h-11 sm:h-10 rounded-md border border-[var(--surface-border)] bg-[var(--surface)] ps-9 px-3 py-2 text-sm text-[var(--foreground)] placeholder:text-[var(--text-faint)] outline-none focus:border-[var(--surface-border-strong)]"
              />
              <LockIcon className="absolute left-3 top-3.5 sm:top-3 size-4 text-[var(--text-faint)] pointer-events-none" />
            </div>

            {error && <p className="text-red-500 text-sm">{error}</p>}

            <button
              type="submit"
              disabled={loading}
              className="w-full h-11 rounded-md bg-neutral-900 dark:bg-neutral-50 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50"
            >
              {loading ? "Signing in..." : "Sign In"}
            </button>
          </form>

          <p className="text-[var(--text-faint)] mt-6 sm:mt-8 text-xs sm:text-sm">
            Demo build - any email / password combination signs you in.
          </p>
        </div>
      </div>
    </main>
  );
}

"use client";

import { use, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useRouter } from "next/navigation";
import { useNavigationLoading } from "@/lib/navigation-loading-context";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { useStore } from "@/lib/store";
import { overheadSchema, type OverheadFormValues } from "@/lib/schemas";

function OverheadDialog({ open, onClose, batchId }: { open: boolean; onClose: () => void; batchId: string }) {
  const allocateOverhead = useStore((s) => s.allocateOverhead);
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<OverheadFormValues>({
    resolver: zodResolver(overheadSchema),
    defaultValues: { electricity: 0, gas: 0, rent: 0 },
  });

  if (!open) return null;

  const onSubmit = async (values: OverheadFormValues) => {
    allocateOverhead(batchId, values.electricity, values.gas, values.rent);
    toast.success(`Overhead of Rs. ${(values.electricity + values.gas + values.rent).toLocaleString()} allocated to ${batchId}`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Allocate Month-End Overhead</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Electricity</label>
            <input {...register("electricity")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.electricity && <p className="text-xs text-red-400 mt-1">{errors.electricity.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Gas</label>
            <input {...register("gas")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.gas && <p className="text-xs text-red-400 mt-1">{errors.gas.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Rent</label>
            <input {...register("rent")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.rent && <p className="text-xs text-red-400 mt-1">{errors.rent.message}</p>}
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting}
            className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function BatchDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const router = useRouter();
  const { navigate } = useNavigationLoading();
  const batch = useStore((s) => s.productionBatches.find((b) => b.id === id));
  const [dialogOpen, setDialogOpen] = useState(false);

  if (!batch) {
    return (
      <div className="space-y-4">
        <NavLink href="/batches" className="text-sm text-[var(--text-muted)] hover:underline">&larr; Back to Batches</NavLink>
        <p className="text-[var(--text-muted)]">Batch not found.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <NavLink href="/batches" className="hover:underline text-[var(--text-secondary)]">Batches</NavLink>{" "}
        / <span className="text-[var(--foreground)]">{batch.id}</span>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">{batch.id}</h1>
        <p className="text-sm text-[var(--text-muted)] mt-1">Batch Date: {batch.batchDate}</p>

        <div className="mt-5 grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div>
            <div className="text-[var(--text-muted)] text-xs">Output Yield</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{batch.outputYieldKg} kg</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Wastage</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{batch.wastageKg} kg</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Leftover Remaining</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{batch.leftoverQtyKg} kg</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Effective Cost/Kg</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">
              Rs. {batch.bulkCostPerKg.toLocaleString(undefined, { maximumFractionDigits: 2 })}
            </div>
          </div>
        </div>

        {batch.overheadTotal > 0 && (
          <div className="mt-4 text-xs text-amber-400">
            Overhead of Rs. {batch.overheadTotal.toLocaleString()} allocated across this batch's output.
          </div>
        )}

        {batch.leftoverSourceBatchId && batch.leftoverKgConsumed && (
          <div className="mt-2 text-xs text-blue-400">
            Includes {batch.leftoverKgConsumed} kg of leftover bulk product carried forward from{" "}
            <NavLink href={`/batches/${batch.leftoverSourceBatchId}`} className="underline">{batch.leftoverSourceBatchId}</NavLink>{" "}
            (FIFO — cost blended into this batch's effective cost/kg).
          </div>
        )}
      </div>

      <div className="flex gap-2">
        <button onClick={() => setDialogOpen(true)} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
          Allocate Month-End Overhead
        </button>
        <button onClick={() => navigate(`/finished-cartons?batchId=${batch.id}`)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          Send to Packaging
        </button>
      </div>

      <OverheadDialog open={dialogOpen} onClose={() => setDialogOpen(false)} batchId={batch.id} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { useNavigationLoading } from "@/lib/navigation-loading-context";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { useStore } from "@/lib/store";
import { batchSchema, type BatchFormValues } from "@/lib/schemas";

type ConsumptionRow = { id: string; rawMaterialId: string; qty: string };

export default function NewBatchPage() {
  const router = useRouter();
  const { navigate } = useNavigationLoading();
  const rawMaterials = useStore((s) => s.rawMaterials);
  const productionBatches = useStore((s) => s.productionBatches);
  const createBatch = useStore((s) => s.createBatch);

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<BatchFormValues>({
    resolver: zodResolver(batchSchema),
    defaultValues: { outputYieldKg: 0, wastageKg: 0 },
  });
  const outputYield = watch("outputYieldKg");

  const [rows, setRows] = useState<ConsumptionRow[]>([
    { id: crypto.randomUUID(), rawMaterialId: rawMaterials[0]?.id ?? "", qty: "" },
  ]);
  const [rowError, setRowError] = useState("");
  const [useLeftoverFirst, setUseLeftoverFirst] = useState(false);
  const [leftoverBatchId, setLeftoverBatchId] = useState("");
  const [leftoverKgUsed, setLeftoverKgUsed] = useState("");

  const leftoverBatches = productionBatches.filter((b) => b.leftoverQtyKg > 0);
  const selectedLeftoverBatch = leftoverBatches.find((b) => b.id === leftoverBatchId);

  const addRow = () => setRows((prev) => [...prev, { id: crypto.randomUUID(), rawMaterialId: rawMaterials[0]?.id ?? "", qty: "" }]);
  const removeRow = (id: string) => setRows((prev) => (prev.length > 1 ? prev.filter((r) => r.id !== id) : prev));
  const updateRow = (id: string, patch: Partial<ConsumptionRow>) =>
    setRows((prev) => prev.map((r) => (r.id === id ? { ...r, ...patch } : r)));

  const estimatedRawMaterialCost = useMemo(() => {
    return rows.reduce((total, row) => {
      const material = rawMaterials.find((m) => m.id === row.rawMaterialId);
      const qty = Number(row.qty) || 0;
      if (!material) return total;
      return total + qty * material.avgUnitCost;
    }, 0);
  }, [rows, rawMaterials]);

  const estimatedLeftoverCost = useMemo(() => {
    if (!useLeftoverFirst || !selectedLeftoverBatch) return 0;
    const kg = Math.min(Number(leftoverKgUsed) || 0, selectedLeftoverBatch.leftoverQtyKg);
    return kg * selectedLeftoverBatch.bulkCostPerKg;
  }, [useLeftoverFirst, selectedLeftoverBatch, leftoverKgUsed]);

  const estimatedTotalCost = estimatedRawMaterialCost + estimatedLeftoverCost;

  const effectiveKgUsedFromLeftover = useMemo(() => {
    if (!useLeftoverFirst || !selectedLeftoverBatch) return 0;
    return Math.min(Number(leftoverKgUsed) || 0, selectedLeftoverBatch.leftoverQtyKg);
  }, [useLeftoverFirst, selectedLeftoverBatch, leftoverKgUsed]);

  const estimatedTotalKg = (Number(outputYield) || 0) + effectiveKgUsedFromLeftover;

  const estimatedCostPerKg = useMemo(() => {
    if (estimatedTotalKg <= 0) return 0;
    return estimatedTotalCost / estimatedTotalKg;
  }, [estimatedTotalCost, estimatedTotalKg]);

  const onSubmit = async (values: BatchFormValues) => {
    setRowError("");
    const consumptions = rows
      .filter((r) => r.rawMaterialId && Number(r.qty) > 0)
      .map((r) => ({ rawMaterialId: r.rawMaterialId, qty: Number(r.qty) }));

    if (consumptions.length === 0) {
      setRowError("Add at least one raw material row with a quantity greater than 0");
      return;
    }

    const insufficient = consumptions.find((c) => {
      const m = rawMaterials.find((rm) => rm.id === c.rawMaterialId);
      return m && c.qty > m.quantityInStock;
    });
    if (insufficient) {
      setRowError("Not enough stock for one of the selected raw materials");
      return;
    }

    if (useLeftoverFirst) {
      if (!leftoverBatchId) {
        setRowError("Select a leftover batch, or turn off 'Use Leftover From Previous Batch First'");
        return;
      }
      const kg = Number(leftoverKgUsed) || 0;
      if (kg <= 0) {
        setRowError("Enter how many kg of leftover to use");
        return;
      }
      if (selectedLeftoverBatch && kg > selectedLeftoverBatch.leftoverQtyKg) {
        setRowError(`Only ${selectedLeftoverBatch.leftoverQtyKg} kg leftover available in ${selectedLeftoverBatch.id}`);
        return;
      }
    }

    const newId = createBatch({
      consumptions,
      outputYieldKg: values.outputYieldKg,
      wastageKg: values.wastageKg,
      leftoverBatchId: useLeftoverFirst ? leftoverBatchId : undefined,
      leftoverKgUsed: useLeftoverFirst ? Number(leftoverKgUsed) || 0 : undefined,
    });

    if (useLeftoverFirst) {
      toast.success(`Batch ${newId} created — raw material stock deducted and ${leftoverKgUsed} kg leftover from ${leftoverBatchId} consumed`);
    } else {
      toast.success(`Batch ${newId} created — raw material stock deducted`);
    }
    navigate(`/batches/${newId}`);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6 max-w-3xl">
      <h1 className="text-xl font-semibold text-[var(--foreground)]">New Production Batch</h1>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-sm font-semibold text-[var(--foreground)]">Raw Material Consumption</h2>
          <button type="button" onClick={addRow} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-xs text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
            + Add Material Row
          </button>
        </div>

        <div className="space-y-3">
          {rows.map((row) => {
            const material = rawMaterials.find((m) => m.id === row.rawMaterialId);
            return (
              <div key={row.id} className="space-y-1">
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
                  <select value={row.rawMaterialId} onChange={(e) => updateRow(row.id, { rawMaterialId: e.target.value })}
                    className="flex-1 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                    {rawMaterials.map((m) => (
                      <option key={m.id} value={m.id}>{m.name} ({m.unit}) — {m.quantityInStock} in stock</option>
                    ))}
                  </select>
                  <input value={row.qty} onChange={(e) => updateRow(row.id, { qty: e.target.value })} type="number" placeholder="Qty"
                    className="w-full sm:w-28 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
                  <button type="button" onClick={() => removeRow(row.id)} className="rounded-lg border border-[var(--surface-border)] px-3 py-2 text-sm text-[var(--text-muted)] hover:bg-[var(--surface-hover)]">-</button>
                </div>
                {material && Number(row.qty) > material.quantityInStock && (
                  <p className="text-xs text-red-400">Only {material.quantityInStock} {material.unit} available</p>
                )}
              </div>
            );
          })}
          {rowError && <p className="text-xs text-red-400">{rowError}</p>}
        </div>

        <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-4">
          <div className="text-xs text-[var(--text-muted)]">Estimated Batch Cost</div>
          <div className="text-lg font-semibold text-[var(--foreground)] mt-1">
            Rs. {estimatedTotalCost.toLocaleString(undefined, { maximumFractionDigits: 2 })}
          </div>
          {estimatedLeftoverCost > 0 && (
            <div className="text-xs text-[var(--text-faint)] mt-1">
              includes Rs. {estimatedLeftoverCost.toLocaleString(undefined, { maximumFractionDigits: 2 })} carried over from leftover
            </div>
          )}
          {estimatedTotalKg > 0 && (
            <div className="text-xs text-[var(--text-muted)] mt-1">
              Est. cost/kg: Rs. {estimatedCostPerKg.toLocaleString(undefined, { maximumFractionDigits: 2 })}
              {" "}(on {estimatedTotalKg} kg total{effectiveKgUsedFromLeftover > 0 ? `, incl. ${effectiveKgUsedFromLeftover} kg leftover` : ""})
            </div>
          )}
        </div>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <label className="text-sm text-[var(--text-muted)]">Output Yield (kg)</label>
          <input {...register("outputYieldKg")} type="number" step="any"
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.outputYieldKg && <p className="text-xs text-red-400 mt-1">{errors.outputYieldKg.message}</p>}
        </div>
        <div>
          <label className="text-sm text-[var(--text-muted)]">Wastage (kg)</label>
          <input {...register("wastageKg")} type="number" step="any"
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.wastageKg && <p className="text-xs text-red-400 mt-1">{errors.wastageKg.message}</p>}
        </div>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-3">
        <label className="flex items-center gap-3 cursor-pointer">
          <input
            type="checkbox"
            checked={useLeftoverFirst}
            onChange={(e) => {
              setUseLeftoverFirst(e.target.checked);
              if (!e.target.checked) {
                setLeftoverBatchId("");
                setLeftoverKgUsed("");
              }
            }}
            className="size-4 rounded border-[var(--surface-border-strong)] bg-[var(--background)]"
          />
          <span className="text-sm text-[var(--foreground)]">Use Leftover From Previous Batch First</span>
        </label>

        {useLeftoverFirst && (
          <div className="space-y-3">
            <div>
              <label className="text-sm text-[var(--text-muted)]">Leftover Batch</label>
              <select
                value={leftoverBatchId}
                onChange={(e) => { setLeftoverBatchId(e.target.value); setLeftoverKgUsed(""); }}
                className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]"
              >
                <option value="">Select leftover batch...</option>
                {leftoverBatches.map((b) => (
                  <option key={b.id} value={b.id}>{b.id} — {b.leftoverQtyKg} kg available @ Rs. {b.bulkCostPerKg}/kg</option>
                ))}
              </select>
            </div>

            {selectedLeftoverBatch && (
              <div>
                <label className="text-sm text-[var(--text-muted)]">Leftover Qty to Use (kg)</label>
                <input
                  value={leftoverKgUsed}
                  onChange={(e) => setLeftoverKgUsed(e.target.value)}
                  type="number"
                  step="any"
                  max={selectedLeftoverBatch.leftoverQtyKg}
                  placeholder={`Up to ${selectedLeftoverBatch.leftoverQtyKg} kg`}
                  className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]"
                />
                {Number(leftoverKgUsed) > selectedLeftoverBatch.leftoverQtyKg && (
                  <p className="text-xs text-red-400 mt-1">Only {selectedLeftoverBatch.leftoverQtyKg} kg available in this batch</p>
                )}
              </div>
            )}
          </div>
        )}
      </div>

      <div className="flex justify-end gap-2">
        <button type="button" onClick={() => navigate("/batches")} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
        <button type="submit" disabled={isSubmitting}
          className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
          {isSubmitting ? "Saving..." : "Save Batch"}
        </button>
      </div>
    </form>
  );
}

"use client";

import { useMemo } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type ProductionBatch } from "@/lib/store";
import { SortableTable } from "@/components/ui/sortable-table";

function StatusBadge({ status }: { status: "in_progress" | "completed" }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
      status === "completed" ? "bg-green-950 text-green-400 border border-green-900" : "bg-amber-950 text-amber-400 border border-amber-900"
    }`}>
      {status === "completed" ? "Completed" : "In Progress"}
    </span>
  );
}

export default function BatchesPage() {
  const productionBatches = useStore((s) => s.productionBatches);

  const columns = useMemo<ColumnDef<ProductionBatch, unknown>[]>(() => [
    {
      accessorKey: "id", header: "Batch ID",
      cell: ({ row }) => <NavLink href={`/batches/${row.original.id}`} className="text-[var(--foreground)] hover:underline">{row.original.id}</NavLink>,
    },
    { accessorKey: "batchDate", header: "Date" },
    { accessorKey: "outputYieldKg", header: "Output Yield (kg)" },
    { accessorKey: "wastageKg", header: "Wastage (kg)" },
    { accessorKey: "leftoverQtyKg", header: "Leftover (kg)" },
    {
      accessorKey: "bulkCostPerKg", header: "Bulk Cost/Kg",
      cell: ({ getValue }) => {
        const v = getValue() as number;
        return v > 0 ? `Rs. ${v.toLocaleString()}` : "-";
      },
    },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge status={row.original.status} />,
    },
  ], []);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Production Batches</h1>
        <NavLink href="/batches/new" className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + New Batch
        </NavLink>
      </div>
      <SortableTable data={productionBatches} columns={columns} globalFilterPlaceholder="Search batches..." />
    </div>
  );
}

"use client";

import { use, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useRouter } from "next/navigation";
import { useNavigationLoading } from "@/lib/navigation-loading-context";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { useStore, type LedgerDirection } from "@/lib/store";
import { z } from "zod";

const paymentAmountSchema = z.object({
  amount: z.coerce.number().positive("Amount must be greater than 0"),
  direction: z.enum(["received", "given"], {
    required_error: "Select a direction",
  }),
  note: z.string().trim().optional(),
});
type PaymentAmountValues = z.infer<typeof paymentAmountSchema>;

function RecordPaymentDialog({ open, onClose, customerId }: { open: boolean; onClose: () => void; customerId: string }) {
  const recordLedgerEntry = useStore((s) => s.recordLedgerEntry);
  const {
    register,
    handleSubmit,
    reset,
    watch,
    setValue,
    formState: { errors, isSubmitting },
  } = useForm<PaymentAmountValues>({
    resolver: zodResolver(paymentAmountSchema),
    defaultValues: { amount: 0, direction: "received", note: "" },
  });
  const direction = watch("direction");

  if (!open) return null;

  const onSubmit = async (values: PaymentAmountValues) => {
    recordLedgerEntry(customerId, values.amount, values.direction, values.note ?? "");
    toast.success(
      values.direction === "received"
        ? `Payment of Rs. ${values.amount.toLocaleString()} received`
        : `Rs. ${values.amount.toLocaleString()} recorded as given / credit adjustment`
    );
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Record Payment</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Amount</label>
            <input {...register("amount")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.amount && <p className="text-xs text-red-400 mt-1">{errors.amount.message}</p>}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <label className="text-sm text-[var(--text-muted)]">Direction</label>
              <span
                title='Received = payment received from customer, reduces what they owe. Given = amount given to customer (refund) or a credit adjustment in their favor.'
                className="flex h-3.5 w-3.5 cursor-help items-center justify-center rounded-full border border-[var(--text-faint)] text-[9px] leading-none text-[var(--text-faint)]"
              >
                i
              </span>
            </div>
            <div className="mt-1 grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setValue("direction", "received", { shouldValidate: true })}
                className={`rounded-lg border px-3 py-2 text-xs font-medium transition-colors ${
                  direction === "received"
                    ? "border-green-500 bg-green-500/10 text-green-400"
                    : "border-[var(--surface-border)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                }`}
              >
                + Received from customer
              </button>
              <button
                type="button"
                onClick={() => setValue("direction", "given", { shouldValidate: true })}
                className={`rounded-lg border px-3 py-2 text-xs font-medium transition-colors ${
                  direction === "given"
                    ? "border-red-500 bg-red-500/10 text-red-400"
                    : "border-[var(--surface-border)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                }`}
              >
                âˆ’ Given / credit adjustment
              </button>
            </div>
            <input type="hidden" {...register("direction")} />
            {errors.direction && <p className="text-xs text-red-400 mt-1">{errors.direction.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Note</label>
            <input {...register("note")} placeholder='e.g. "cash refund", "damaged stock credit"'
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting}
            className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

function DirectionBadge({ direction }: { direction: LedgerDirection | null }) {
  if (!direction) return <span className="text-[var(--text-faint)]">—</span>;
  return direction === "received" ? (
    <span className="rounded-full bg-green-500/10 px-2 py-0.5 text-xs font-medium text-green-400">+ Received</span>
  ) : (
    <span className="rounded-full bg-red-500/10 px-2 py-0.5 text-xs font-medium text-red-400">âˆ’ Given</span>
  );
}

export default function CustomerDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const router = useRouter();
  const { navigate } = useNavigationLoading();
  const customer = useStore((s) => s.customers.find((c) => c.id === id));
  const allLedger = useStore((s) => s.ledgerEntries);
  const [dialogOpen, setDialogOpen] = useState(false);

  const ledger = useMemo(() => allLedger.filter((l) => l.customerId === id), [allLedger, id]);

  if (!customer) {
    return (
      <div className="space-y-4">
        <NavLink href="/customers" className="text-sm text-[var(--text-muted)] hover:underline">&larr; Back to Customers</NavLink>
        <p className="text-[var(--text-muted)]">Customer not found.</p>
      </div>
    );
  }

  const totalInvoiced = ledger.filter((l) => l.type === "invoice").reduce((sum, l) => sum + l.amount, 0);
  const totalPaid = ledger.filter((l) => l.type === "payment").reduce((sum, l) => sum + Math.abs(l.amount), 0);

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <NavLink href="/customers" className="hover:underline text-[var(--text-secondary)]">Customers</NavLink>{" "}
        / <span className="text-[var(--foreground)]">{customer.name}</span>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">{customer.name}</h1>
        <p className="text-sm text-[var(--text-muted)] mt-1">{customer.phone}</p>

        <div className="mt-5 grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <div className="text-[var(--text-muted)] text-xs">Current Balance</div>
            <div className={`text-lg font-semibold mt-1 ${customer.currentBalance > 0 ? "text-red-400" : "text-green-400"}`}>
              Rs. {Math.abs(customer.currentBalance).toLocaleString()}
            </div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Total Invoiced</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">Rs. {totalInvoiced.toLocaleString()}</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Total Paid</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">Rs. {totalPaid.toLocaleString()}</div>
          </div>
        </div>
      </div>

      <div className="flex gap-2">
        <button onClick={() => setDialogOpen(true)} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
          + Record Payment
        </button>
        <button onClick={() => navigate(`/invoices/new?customerId=${customer.id}`)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          New Invoice for this Customer
        </button>
      </div>

      <h2 className="text-lg font-semibold text-[var(--foreground)]">Ledger History</h2>
      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium">Date</th>
              <th className="px-4 py-3 font-medium">Type</th>
              <th className="px-4 py-3 font-medium">Direction</th>
              <th className="px-4 py-3 font-medium">Note</th>
              <th className="px-4 py-3 font-medium">Amount</th>
              <th className="px-4 py-3 font-medium">Running Balance</th>
            </tr>
          </thead>
          <tbody>
            {ledger.map((l) => {
              const isDebit = l.type === "invoice";
              return (
                <tr key={l.id} className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{l.date}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)] capitalize">{l.type}</td>
                  <td className="px-4 py-3"><DirectionBadge direction={l.direction} /></td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{l.note}</td>
                  <td className={`px-4 py-3 ${isDebit ? "text-red-400" : "text-green-400"}`}>
                    {isDebit ? "+" : "âˆ’"} Rs. {l.amount.toLocaleString()}
                  </td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {l.runningBalance.toLocaleString()}</td>
                </tr>
              );
            })}
            {ledger.length === 0 && (
              <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--text-faint)]">No ledger entries yet.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <RecordPaymentDialog open={dialogOpen} onClose={() => setDialogOpen(false)} customerId={customer.id} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Customer } from "@/lib/store";
import { customerSchema, type CustomerFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function BalanceCell({ balance }: { balance: number }) {
  const owes = balance > 0;
  const isZero = balance === 0;
  return (
    <span className={isZero ? "text-[var(--text-muted)]" : owes ? "text-red-400" : "text-green-400"}>
      Rs. {Math.abs(balance).toLocaleString()} {!isZero && (owes ? "(owes)" : "(credit)")}
    </span>
  );
}

function AddCustomerDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const addCustomer = useStore((s) => s.addCustomer);
  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm<CustomerFormValues>({
    resolver: zodResolver(customerSchema),
    defaultValues: { name: "", phone: "", openingBalance: 0 },
  });
  if (!open) return null;
  const onSubmit = async (values: CustomerFormValues) => {
    addCustomer(values);
    toast.success(`Customer "${values.name}" added`);
