"use client";

import { useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { toast } from "sonner";
import { useStore, computePackagingUnitCost } from "@/lib/store";
import { InfoTip } from "@/components/ui/info-tip";

// Mirrors the store's internal createPackingRun estimate exactly, so the
// preview shown here never disagrees with what actually gets deducted.
const NOMINAL_KG_PER_PACKET = 0.05;

function AvailabilityRow({
  label, needed, available, unit,
}: { label: string; needed: number; available: number; unit: string }) {
  const short = needed > available;
  return (
    <div className={`flex items-center justify-between rounded-lg border px-3 py-2 text-xs ${
      short ? "border-red-900 bg-red-950/40" : "border-[var(--surface-border)] bg-[var(--background)]"
    }`}>
      <span className="text-[var(--text-muted)]">{label}</span>
      <span className={short ? "text-red-400 font-medium" : "text-[var(--foreground)]"}>
        Needed: {needed.toLocaleString(undefined, { maximumFractionDigits: 2 })} {unit}
        <span className="text-[var(--text-muted)] mx-1">/</span>
        Available: {available.toLocaleString(undefined, { maximumFractionDigits: 2 })} {unit}
        {short && <span className="ml-1">(short)</span>}
      </span>
    </div>
  );
}

function NewPackingRunDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const productionBatches = useStore((s) => s.productionBatches);
  const cartonConfigurations = useStore((s) => s.cartonConfigurations);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const createPackingRun = useStore((s) => s.createPackingRun);

  const [step, setStep] = useState(1);
  const [batchId, setBatchId] = useState(productionBatches.find((b) => b.leftoverQtyKg > 0)?.id ?? productionBatches[0]?.id ?? "");
  const [configId, setConfigId] = useState(cartonConfigurations[0]?.id ?? "");
  const [cartonsProduced, setCartonsProduced] = useState("10");

  const batch = productionBatches.find((b) => b.id === batchId);
  const config = cartonConfigurations.find((c) => c.id === configId);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrapper = wrappers.find((w) => w.id === config?.wrapperId);
  const box = boxes.find((b) => b.id === config?.boxId);
  const wrapperRawMaterial = rawMaterials.find((m) => m.id === wrapper?.rawMaterialId);
  const boxRawMaterial = rawMaterials.find((m) => m.id === box?.rawMaterialId);

  const cartons = Number(cartonsProduced) || 0;
  const boxesNeeded = config ? cartons * config.boxesPerCarton : 0;
  const packetsNeeded = config ? boxesNeeded * config.packetsPerBox : 0;
  const bulkKgNeeded = packetsNeeded * NOMINAL_KG_PER_PACKET;

  const bulkAvailable = batch?.leftoverQtyKg ?? 0;
  const wrapperAvailable = wrapper?.stockQty ?? 0;
  const boxAvailable = box?.stockQty ?? 0;

  const insufficientBulk = bulkKgNeeded > bulkAvailable;
  const insufficientWrapper = packetsNeeded > wrapperAvailable;
  const insufficientBox = boxesNeeded > boxAvailable;
  const anyInsufficient = insufficientBulk || insufficientWrapper || insufficientBox;

  const showAvailabilityPanel = !!(batch && config && cartons > 0);

  // Preview estimate - mirrors the store's internal calculation
  // IMPORTANT: this hook must run on every render (even when the dialog is
  // closed) - never put a conditional "return null" before a hook call.
  const preview = useMemo(() => {
    if (!open || !batch || !config || !wrapper || !box || cartons <= 0) return null;
    const bulkKgUsed = Math.min(bulkKgNeeded, batch.leftoverQtyKg);
    const bulkCostShare = batch.bulkCostPerKg * bulkKgUsed;
    const wrapperUnitCostValue = computePackagingUnitCost(wrapper.gramsPerUnit, wrapperRawMaterial);
    const boxUnitCostValue = computePackagingUnitCost(box.gramsPerUnit, boxRawMaterial);
    const costPerPacket = packetsNeeded > 0 ? bulkCostShare / packetsNeeded + wrapperUnitCostValue : wrapperUnitCostValue;
    const costPerBox = config.packetsPerBox * costPerPacket + boxUnitCostValue;
    const costPerCarton = config.boxesPerCarton * costPerBox;
    return { bulkKgUsed, costPerPacket, costPerBox, costPerCarton };
  }, [open, batch, config, wrapper, box, cartons, packetsNeeded, bulkKgNeeded]);

  if (!open) return null;

  const reset = () => {
    setStep(1);
    setCartonsProduced("10");
  };

  const handleConfirm = () => {
    if (!batch || !config) return;
    if (cartons <= 0) {
      toast.error("Enter a valid number of cartons");
      return;
    }
    if (insufficientBulk) {
      toast.error("Not enough bulk product left in the selected batch");
      return;
    }
    if (insufficientWrapper) {
      toast.error(`Not enough ${wrapper?.name} in stock`);
      return;
    }
    if (insufficientBox) {
      toast.error(`Not enough ${box?.name} in stock`);
      return;
    }
    createPackingRun({ batchId, configId, cartonsProduced: cartons });
    toast.success(`Packing run confirmed - ${cartons} cartons added to ready stock`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <div className="w-full max-w-md rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">New Packing Run - Step {step} of 3</h2>

        {step === 1 && (
          <div>
            <label className="text-sm text-[var(--text-muted)]">Select Batch</label>
            <select value={batchId} onChange={(e) => setBatchId(e.target.value)}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
              {productionBatches.map((b) => (
                <option key={b.id} value={b.id}>{b.id} - {b.leftoverQtyKg} kg available</option>
              ))}
            </select>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-3">
            <div>
              <label className="text-sm text-[var(--text-muted)]">Carton Configuration</label>
              <select value={configId} onChange={(e) => setConfigId(e.target.value)}
                className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                {cartonConfigurations.length === 0 && <option value="">No configurations available</option>}
                {cartonConfigurations.map((c) => (
                  <option key={c.id} value={c.id}>{c.name}{c.usedInPackingRun ? " (used before)" : ""}</option>
                ))}
              </select>
              {cartonConfigurations.length === 0 && (
                <p className="text-xs text-red-400 mt-1">
                  No carton configurations exist yet. Create one under{" "}
                  <NavLink href="/packaging/carton-config" className="underline">Packaging &rarr; Carton Configurations</NavLink>.
                </p>
              )}
            </div>
            <div>
              <label className="text-sm text-[var(--text-muted)]">Number of Cartons Produced</label>
              <input value={cartonsProduced} onChange={(e) => setCartonsProduced(e.target.value)} type="number"
                className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            </div>

            {showAvailabilityPanel && (
              <div className="space-y-2">
                <div className="flex items-center text-xs font-medium text-[var(--text-muted)]">
                  Needed vs. Available
                  <InfoTip text="How much of each input the requested Cartons Produced will consume, versus how much is currently in stock. All three must be sufficient before you can confirm." />
                </div>
                <AvailabilityRow label="Bulk Material" needed={bulkKgNeeded} available={bulkAvailable} unit="kg" />
                <AvailabilityRow label="Boxes" needed={boxesNeeded} available={boxAvailable} unit="pcs" />
                <AvailabilityRow label="Wrapper" needed={packetsNeeded} available={wrapperAvailable} unit="pcs" />
                {anyInsufficient && (
                  <p className="text-xs text-red-400">
                    Reduce the carton count or restock the shortfall above before continuing.
                  </p>
                )}
              </div>
            )}
          </div>
        )}

        {step === 3 && (
          <div className="space-y-3">
            <div className="space-y-2">
              <div className="flex items-center text-xs font-medium text-[var(--text-muted)]">
                Needed vs. Available
                <InfoTip text="How much of each input the requested Cartons Produced will consume, versus how much is currently in stock. All three must be sufficient before you can confirm." />
              </div>
              <AvailabilityRow label="Bulk Material" needed={bulkKgNeeded} available={bulkAvailable} unit="kg" />
              <AvailabilityRow label="Boxes" needed={boxesNeeded} available={boxAvailable} unit="pcs" />
              <AvailabilityRow label="Wrapper" needed={packetsNeeded} available={wrapperAvailable} unit="pcs" />
            </div>
            <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-4 space-y-2">
              <div className="flex justify-between text-sm"><span className="text-[var(--text-muted)]">Source Batch</span><span className="text-[var(--foreground)]">{batchId}</span></div>
              <div className="flex justify-between text-sm"><span className="text-[var(--text-muted)]">Configuration</span><span className="text-[var(--foreground)]">{config?.name ?? "-"}</span></div>
              <div className="flex justify-between text-sm"><span className="text-[var(--text-muted)]">Cartons Produced</span><span className="text-[var(--foreground)]">{cartons}</span></div>
              {preview && (
                <>
                  <div className="flex justify-between text-sm"><span className="text-[var(--text-muted)]">Bulk Product Used</span><span className="text-[var(--foreground)]">{preview.bulkKgUsed.toFixed(2)} kg</span></div>
                  <div className="flex justify-between text-sm pt-2 border-t border-[var(--surface-border)]">
                    <span className="text-[var(--text-muted)]">Est. Cost / Packet</span>
                    <span className="text-[var(--foreground)]">Rs. {preview.costPerPacket.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-[var(--text-muted)]">Est. Cost / Box</span>
                    <span className="text-[var(--foreground)]">Rs. {preview.costPerBox.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="inline-flex items-center text-[var(--text-muted)]">
                      Est. Cost / Carton
                      <InfoTip text="Cost per packet (bulk share + wrapper) x packets per box, plus box cost, x boxes per carton." />
                    </span>
                    <span className="text-[var(--foreground)] font-semibold">Rs. {preview.costPerCarton.toFixed(2)}</span>
                  </div>
                </>
              )}
            </div>
          </div>
        )}

        <div className="flex justify-between pt-2">
          <button onClick={() => (step === 1 ? onClose() : setStep(step - 1))} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">
            {step === 1 ? "Cancel" : "Back"}
          </button>
          {step < 3 ? (
            <button
              onClick={() => setStep(step + 1)}
              disabled={step === 2 && (!config || cartons <= 0 || anyInsufficient)}
              className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50"
            >
              Next
            </button>
          ) : (
            <button onClick={handleConfirm} disabled={anyInsufficient} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
              Confirm Packing
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export default function FinishedCartonsPage() {
  const cartons = useStore((s) => s.finishedCartons);
  const productionBatches = useStore((s) => s.productionBatches);
  const [tab, setTab] = useState<"ready" | "leftover">("ready");
  const [dialogOpen, setDialogOpen] = useState(false);

  const leftoverBatches = productionBatches.filter((b) => b.leftoverQtyKg > 0);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Finished Cartons</h1>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + New Packing Run
        </button>
      </div>

      <div className="flex gap-2 border-b border-[var(--surface-border)]">
        <button onClick={() => setTab("ready")} className={`px-4 py-2 text-sm font-medium border-b-2 ${tab === "ready" ? "border-neutral-900 dark:border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"}`}>
          Ready for Sale
        </button>
        <button onClick={() => setTab("leftover")} className={`px-4 py-2 text-sm font-medium border-b-2 ${tab === "leftover" ? "border-neutral-900 dark:border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"}`}>
          Unpacked / Leftover
        </button>
      </div>

      {tab === "ready" ? (
        <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
                <th className="px-4 py-3 font-medium">Carton</th>
                <th className="px-4 py-3 font-medium">Source Batch</th>
                <th className="px-4 py-3 font-medium">Cartons Produced</th>
                <th className="px-4 py-3 font-medium">Packets/Carton</th>
                <th className="px-4 py-3 font-medium">Cost/Packet</th>
                <th className="px-4 py-3 font-medium">Cost/Box</th>
                <th className="px-4 py-3 font-medium">Cost/Carton</th>
                <th className="px-4 py-3 font-medium">Stock Qty</th>
              </tr>
            </thead>
            <tbody>
              {cartons.map((c) => (
                <tr key={c.id} className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                  <td className="px-4 py-3 text-[var(--foreground)]">{c.name}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{c.sourceBatchId}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{c.cartonsProduced}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{c.packetsPerCarton}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {c.costPerPacket.toLocaleString()}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {c.costPerBox.toLocaleString()}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {c.costPerCarton.toLocaleString()}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{c.stockQty}</td>
                </tr>
              ))}
              {cartons.length === 0 && (
                <tr><td colSpan={8} className="px-4 py-8 text-center text-[var(--text-faint)]">No finished cartons yet.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
                <th className="px-4 py-3 font-medium">Batch</th>
                <th className="px-4 py-3 font-medium">Leftover Bulk (kg)</th>
                <th className="px-4 py-3 font-medium">Bulk Cost/Kg</th>
              </tr>
            </thead>
            <tbody>
              {leftoverBatches.map((b) => (
                <tr key={b.id} className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                  <td className="px-4 py-3 text-[var(--foreground)]">{b.id}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{b.leftoverQtyKg} kg</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {b.bulkCostPerKg.toLocaleString()}</td>
                </tr>
              ))}
              {leftoverBatches.length === 0 && (
                <tr><td colSpan={3} className="px-4 py-8 text-center text-[var(--text-faint)]">No leftover bulk product.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      <NewPackingRunDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

"use client";

import { use, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { useStore } from "@/lib/store";
import { z } from "zod";

const paymentAmountSchema = z.object({
  amount: z.coerce.number().positive("Amount must be greater than 0"),
});
type PaymentAmountValues = z.infer<typeof paymentAmountSchema>;

function RecordPaymentDialog({ open, onClose, customerId, customerName }: { open: boolean; onClose: () => void; customerId: string; customerName: string }) {
  // NOTE: this dialog still only records a "received" payment with no
  // direction selector. The full +/- direction UI (BRS v1.2 item 6 /
  // Spec v2.2 5.12) is Step 7 scope. This wiring is switched from the
  // removed s.recordPayment() to the real s.recordLedgerEntry() so the
  // page compiles against the current store in the meantime.
  const recordLedgerEntry = useStore((s) => s.recordLedgerEntry);
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<PaymentAmountValues>({ resolver: zodResolver(paymentAmountSchema) });

  if (!open) return null;

  const onSubmit = async (values: PaymentAmountValues) => {
    recordLedgerEntry(customerId, values.amount, "received", "Payment against invoice");
    toast.success(`Payment of Rs. ${values.amount.toLocaleString()} recorded for ${customerName}`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Record Payment \u2014 {customerName}</h2>
        <div>
          <label className="text-sm text-[var(--text-muted)]">Amount</label>
          <input {...register("amount")} type="number" step="any"
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.amount && <p className="text-xs text-red-400 mt-1">{errors.amount.message}</p>}
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting}
            className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

// "<- Back" (Spec v2.2 5.10): router.back() when we can tell the visit came
// from within this app (document.referrer on the same origin), otherwise a
// same-tab fallback push to /invoices. document.referrer is only available
// client-side, so this is computed in an effect and defaults to the safe
// fallback (push) until it resolves.
function BackButton() {
  const router = useRouter();
  const [cameFromApp, setCameFromApp] = useState(false);

  useEffect(() => {
    try {
      setCameFromApp(Boolean(document.referrer) && document.referrer.startsWith(window.location.origin));
    } catch {
      setCameFromApp(false);
    }
  }, []);

  const handleBack = () => {
    if (cameFromApp) {
      router.back();
    } else {
      router.push("/invoices");
    }
  };

  return (
    <button
      type="button"
      onClick={handleBack}
      className="inline-flex items-center gap-1.5 rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)] print:hidden"
    >
      &larr; Back
    </button>
  );
}

export default function InvoiceDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const invoice = useStore((s) => s.invoices.find((i) => i.id === id));
  const settings = useStore((s) => s.settings);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [generatingPdf, setGeneratingPdf] = useState(false);

  if (!invoice) {
    return (
      <div className="space-y-4">
        <NavLink href="/invoices" className="text-sm text-[var(--text-muted)] hover:underline">&larr; Back to Invoices</NavLink>
        <p className="text-[var(--text-muted)]">Invoice not found.</p>
      </div>
    );
  }

  const handleDownloadPDF = async () => {
    setGeneratingPdf(true);
    try {
      const { jsPDF } = await import("jspdf");
      const doc = new jsPDF({ unit: "pt", format: "a4" });

      const marginX = 48;
      let y = 56;

      doc.setFontSize(18);
      doc.setFont("helvetica", "bold");
      doc.text(settings.businessName || "GhaniFoods", marginX, y);

      doc.setFontSize(9);
      doc.setFont("helvetica", "normal");
      y += 16;
      doc.text(settings.address || "", marginX, y);

      doc.setFontSize(20);
      doc.setFont("helvetica", "bold");
      doc.text("INVOICE", 595 - marginX, 56, { align: "right" });
      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.text(invoice.id, 595 - marginX, 74, { align: "right" });
      doc.text(invoice.invoiceDate, 595 - marginX, 88, { align: "right" });

      y += 32;
      doc.setDrawColor(200);
      doc.line(marginX, y, 595 - marginX, y);

      y += 24;
      doc.setFontSize(9);
      doc.setTextColor(120);
      doc.text("BILLED TO", marginX, y);
      y += 14;
      doc.setFontSize(12);
      doc.setTextColor(20);
      doc.setFont("helvetica", "bold");
      doc.text(invoice.customerName, marginX, y);
      doc.setFont("helvetica", "normal");

      y += 30;
      const colItem = marginX;
      const colQty = 330;
      const colPrice = 400;
      const colSubtotal = 500;

      doc.setFillColor(23, 23, 23);
      doc.rect(marginX, y - 14, 595 - marginX * 2, 22, "F");
      doc.setTextColor(255);
      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.text("ITEM", colItem + 6, y + 1);
      doc.text("QTY", colQty, y + 1);
      doc.text("UNIT PRICE", colPrice, y + 1);
      doc.text("SUBTOTAL", colSubtotal, y + 1);

      y += 22;
      doc.setTextColor(30);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);

      const lines = invoice.items.length > 0
        ? invoice.items
        : [{ itemName: "Nimko Carton (legacy record)", qty: 0, unitPrice: 0, subtotal: invoice.totalAmount, itemId: "" }];

      for (const line of lines) {
        doc.text(String(line.itemName), colItem + 6, y);
        doc.text(line.qty ? String(line.qty) : "-", colQty, y);
        doc.text(line.unitPrice ? `Rs. ${line.unitPrice.toLocaleString()}` : "-", colPrice, y);
        doc.text(`Rs. ${line.subtotal.toLocaleString()}`, colSubtotal, y);
        y += 20;
        doc.setDrawColor(230);
        doc.line(marginX, y - 6, 595 - marginX, y - 6);
      }

      y += 20;
      doc.setFont("helvetica", "bold");
      doc.setFontSize(12);
      doc.text("Total:", colPrice, y);
      doc.text(`Rs. ${invoice.totalAmount.toLocaleString()}`, colSubtotal, y);

      y += 50;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.setTextColor(120);
      doc.text(settings.invoiceFooterText || "Thank you for your business!", marginX, y);

      doc.save(`${invoice.id}.pdf`);
      toast.success(`Invoice ${invoice.id} downloaded as PDF`);
    } catch (err) {
      toast.error("Could not generate PDF. Please try again.");
      console.error(err);
    } finally {
      setGeneratingPdf(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between print:hidden">
        <div className="text-sm text-[var(--text-muted)]">
          <NavLink href="/invoices" className="hover:underline text-[var(--text-secondary)]">Invoices</NavLink>{" "}
          / <span className="text-[var(--foreground)]">{invoice.id}</span>
        </div>
        <BackButton />
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-6 print:border-0">
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-xl font-semibold text-[var(--foreground)]">Invoice {invoice.id}</h1>
            <p className="text-sm text-[var(--text-muted)] mt-1">{invoice.invoiceDate}</p>
          </div>
          <div className="text-right">
            <div className="text-[var(--text-muted)] text-xs">Billed To</div>
            <div className="text-[var(--foreground)] font-medium">{invoice.customerName}</div>
          </div>
        </div>

        <div className="mt-6 rounded-lg border border-[var(--surface-border)] overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--surface-border)] bg-[var(--background)] text-left text-[var(--text-muted)]">
                <th className="px-4 py-2 font-medium">Item</th>
                <th className="px-4 py-2 font-medium">Qty</th>
                <th className="px-4 py-2 font-medium">Unit Price</th>
                <th className="px-4 py-2 font-medium">Subtotal</th>
              </tr>
            </thead>
            <tbody>
              {invoice.items.length > 0 ? (
                invoice.items.map((line, idx) => (
                  <tr key={idx}>
                    <td className="px-4 py-2 text-[var(--text-secondary)]">
                      {line.itemName}
                      {line.priceSourceNote && (
                        <div className="mt-0.5 text-xs text-[var(--text-faint)]">{line.priceSourceNote}</div>
                      )}
                    </td>
                    <td className="px-4 py-2 text-[var(--text-secondary)]">{line.qty}</td>
                    <td className="px-4 py-2 text-[var(--text-secondary)]">Rs. {line.unitPrice.toLocaleString()}</td>
                    <td className="px-4 py-2 text-[var(--text-secondary)]">Rs. {line.subtotal.toLocaleString()}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td className="px-4 py-2 text-[var(--text-secondary)]">Nimko Carton (legacy record)</td>
                  <td className="px-4 py-2 text-[var(--text-secondary)]">-</td>
                  <td className="px-4 py-2 text-[var(--text-secondary)]">-</td>
                  <td className="px-4 py-2 text-[var(--text-secondary)]">Rs. {invoice.totalAmount.toLocaleString()}</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        <div className="mt-4 flex justify-end">
          <div className="text-lg font-semibold text-[var(--foreground)]">Total: Rs. {invoice.totalAmount.toLocaleString()}</div>
        </div>
      </div>

      <div className="flex gap-2 print:hidden">
        <button onClick={() => window.print()} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">Print</button>
        <button
          onClick={handleDownloadPDF}
          disabled={generatingPdf}
          className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)] disabled:opacity-50"
        >
          {generatingPdf ? "Generating..." : "Download PDF"}
        </button>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          Record Payment
        </button>
      </div>

      <RecordPaymentDialog open={dialogOpen} onClose={() => setDialogOpen(false)} customerId={invoice.customerId} customerName={invoice.customerName} />
    </div>
  );
}

"use client";

import { Suspense, useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useNavigationLoading } from "@/lib/navigation-loading-context";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { Info } from "lucide-react";
import { useStore } from "@/lib/store";
import { invoiceHeaderSchema, type InvoiceHeaderFormValues } from "@/lib/schemas";

type InvoiceLine = {
  id: string;
  itemId: string;
  qty: string;
  unitPrice: string;
  priceSourceNote: string;
  touched: boolean; // true once the user manually edits the price - stops auto-recalc from overwriting it
};

function buildPriceAndNote(
  itemId: string,
  customerId: string,
  margin: number,
  finishedCartons: { id: string; costPerCarton: number }[],
  lastSoldPriceInfo: (customerId: string, itemId: string) => { price: number; date: string } | undefined,
): { unitPrice: string; priceSourceNote: string } {
  const info = lastSoldPriceInfo(customerId, itemId);
  if (info) {
    return {
      unitPrice: String(info.price),
      priceSourceNote: `Previously sold to this customer on ${info.date} at Rs. ${info.price.toLocaleString()} \u2014 that price applied.`,
    };
  }
  const carton = finishedCartons.find((c) => c.id === itemId);
  const marginMultiplier = 1 + (Number(margin) || 0) / 100;
  const fallback = carton ? Math.round(carton.costPerCarton * marginMultiplier) : 0;
  return {
    unitPrice: String(fallback),
    priceSourceNote: "First sale of this item to this customer \u2014 margin-based price applied.",
  };
}

function NewInvoiceForm() {
  const router = useRouter();
  const { navigate } = useNavigationLoading();
  const searchParams = useSearchParams();
  const preselectedCustomerId = searchParams.get("customerId") ?? "";

  const customers = useStore((s) => s.customers);
  const finishedCartons = useStore((s) => s.finishedCartons);
  const lastSoldPriceInfo = useStore((s) => s.lastSoldPriceInfo);
  const createInvoice = useStore((s) => s.createInvoice);
  const defaultMargin = useStore((s) => s.settings.defaultProfitMarginPercent);

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<InvoiceHeaderFormValues>({
    resolver: zodResolver(invoiceHeaderSchema),
    defaultValues: { customerId: preselectedCustomerId || customers[0]?.id || "", margin: defaultMargin ?? 20 },
  });
  const customerId = watch("customerId");
  const margin = watch("margin");

  const [lines, setLines] = useState<InvoiceLine[]>(() => {
    const firstItemId = finishedCartons[0]?.id ?? "";
    const { unitPrice, priceSourceNote } = buildPriceAndNote(
      firstItemId,
      preselectedCustomerId || customers[0]?.id || "",
      defaultMargin ?? 20,
      finishedCartons,
      lastSoldPriceInfo,
    );
    return [{ id: crypto.randomUUID(), itemId: firstItemId, qty: "1", unitPrice, priceSourceNote, touched: false }];
  });
  const [lineError, setLineError] = useState("");

  // Live recalculation: whenever the customer or the margin changes, refresh
  // the price + price-source note for every line that hasn't been manually
  // edited yet. This is the fix for the "requires a second try" bug - the
  // effect's dependency list includes customerId AND margin AND the set of
  // line itemIds, so a customer swap after an item was already picked
  // recalculates immediately instead of waiting for some other re-render.
  const lineItemIdsKey = lines.map((l) => l.itemId).join("|");
  useEffect(() => {
    if (!customerId) return;
    setLines((prev) =>
      prev.map((line) => {
        if (line.touched || !line.itemId) return line;
        const { unitPrice, priceSourceNote } = buildPriceAndNote(line.itemId, customerId, Number(margin) || 0, finishedCartons, lastSoldPriceInfo);
        return { ...line, unitPrice, priceSourceNote };
      }),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customerId, margin, lineItemIdsKey]);

  const addLine = () => {
    const firstItemId = finishedCartons[0]?.id ?? "";
    const { unitPrice, priceSourceNote } = buildPriceAndNote(firstItemId, customerId, Number(margin) || 0, finishedCartons, lastSoldPriceInfo);
    setLines((prev) => [...prev, { id: crypto.randomUUID(), itemId: firstItemId, qty: "1", unitPrice, priceSourceNote, touched: false }]);
  };
  const removeLine = (id: string) => setLines((prev) => (prev.length > 1 ? prev.filter((l) => l.id !== id) : prev));
  const updateLine = (id: string, patch: Partial<InvoiceLine>) =>
    setLines((prev) => prev.map((l) => (l.id === id ? { ...l, ...patch } : l)));

  const handleItemChange = (id: string, itemId: string) => {
    const { unitPrice, priceSourceNote } = buildPriceAndNote(itemId, customerId, Number(margin) || 0, finishedCartons, lastSoldPriceInfo);
    updateLine(id, { itemId, unitPrice, priceSourceNote, touched: false });
  };

  const handlePriceChange = (id: string, value: string) => updateLine(id, { unitPrice: value, touched: true });

  const total = useMemo(() => lines.reduce((sum, l) => sum + (Number(l.qty) || 0) * (Number(l.unitPrice) || 0), 0), [lines]);

  const onSubmit = async (values: InvoiceHeaderFormValues) => {
    setLineError("");
    const parsedLines = lines
      .filter((l) => l.itemId && Number(l.qty) > 0)
      .map((l) => ({ itemId: l.itemId, qty: Number(l.qty), unitPrice: Number(l.unitPrice) || 0, priceSourceNote: l.priceSourceNote }));

    if (parsedLines.length === 0) {
      setLineError("Add at least one invoice item with a quantity greater than 0");
      return;
    }
    const insufficient = parsedLines.find((l) => {
      const c = finishedCartons.find((fc) => fc.id === l.itemId);
      return c && l.qty > c.stockQty;
    });
    if (insufficient) {
      setLineError("Not enough finished carton stock for one of the items");
      return;
    }
    const invalidPrice = parsedLines.find((l) => l.unitPrice <= 0);
    if (invalidPrice) {
      setLineError("Every line needs a unit price greater than 0");
      return;
    }

    const newId = createInvoice({ customerId: values.customerId, lines: parsedLines });
    toast.success(`Invoice ${newId} created \u2014 stock deducted, ledger updated`);
    navigate(`/invoices/${newId}`);
  };

  const selectedCustomer = customers.find((c) => c.id === customerId);

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6 max-w-3xl">
      <h1 className="text-xl font-semibold text-[var(--foreground)]">New Invoice</h1>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
        <div>
          <label className="text-sm text-[var(--text-muted)]">Customer</label>
          <select {...register("customerId")}
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
            {customers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
          {errors.customerId && <p className="text-xs text-red-400 mt-1">{errors.customerId.message}</p>}
          {selectedCustomer && (
            <p className="text-xs text-[var(--text-faint)] mt-1">
              Current balance: Rs. {Math.abs(selectedCustomer.currentBalance).toLocaleString()}{" "}
              {selectedCustomer.currentBalance > 0 ? "(owes)" : "(credit)"}
            </p>
          )}
        </div>

        <div>
          <label className="flex items-center gap-1.5 text-sm text-[var(--text-muted)]">
            Margin % (used only for items with no price history for this customer)
            <span title="Applied when a line item has never been sold to this customer before. Once an item has a prior price for this customer, that price is recalled instead of the margin.">
              <Info size={14} className="text-[var(--text-faint)]" />
            </span>
          </label>
          <input {...register("margin")} type="number" step="any"
            className="mt-1 w-40 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.margin && <p className="text-xs text-red-400 mt-1">{errors.margin.message}</p>}
        </div>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-sm font-semibold text-[var(--foreground)]">Invoice Items</h2>
          <button type="button" onClick={addLine} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-xs text-[var(--foreground)] hover:bg-[var(--surface-hover)]">+ Add Item</button>
        </div>

        <div className="space-y-3">
          {lines.map((line) => {
            const carton = finishedCartons.find((c) => c.id === line.itemId);
            return (
              <div key={line.id} className="space-y-1">
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
                  <select value={line.itemId} onChange={(e) => handleItemChange(line.id, e.target.value)}
                    className="flex-1 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                    {finishedCartons.map((c) => <option key={c.id} value={c.id}>{c.name} \u2014 {c.stockQty} in stock</option>)}
                  </select>
                  <input value={line.qty} onChange={(e) => updateLine(line.id, { qty: e.target.value })} type="number" placeholder="Qty"
                    className="w-full sm:w-20 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
                  <input value={line.unitPrice} onChange={(e) => handlePriceChange(line.id, e.target.value)} type="number" placeholder="Unit Price"
                    className="w-full sm:w-28 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
                  <button type="button" onClick={() => removeLine(line.id)} className="rounded-lg border border-[var(--surface-border)] px-3 py-2 text-sm text-[var(--text-muted)] hover:bg-[var(--surface-hover)]">-</button>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  {line.priceSourceNote && (
                    <span className="inline-flex items-center gap-1 rounded-full bg-[var(--surface-hover)] px-2.5 py-0.5 text-xs text-[var(--text-secondary)]">
                      {line.priceSourceNote}
                      <span title={line.priceSourceNote}>
                        <Info size={12} className="text-[var(--text-faint)]" />
                      </span>
                    </span>
                  )}
                  {line.touched && (
                    <span className="inline-block rounded-full bg-[var(--surface-hover)] px-2.5 py-0.5 text-xs text-[var(--text-faint)]">
                      Price edited manually
                    </span>
                  )}
                  {carton && Number(line.qty) > carton.stockQty && (
                    <span className="inline-block rounded-full bg-red-950 border border-red-900 px-2.5 py-0.5 text-xs text-red-400">
                      Only {carton.stockQty} in stock
                    </span>
                  )}
                </div>
              </div>
            );
          })}
          {lineError && <p className="text-xs text-red-400">{lineError}</p>}
        </div>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 flex items-center justify-between">
        <span className="text-sm text-[var(--text-muted)]">Total</span>
        <span className="text-2xl font-semibold text-[var(--foreground)]">Rs. {total.toLocaleString()}</span>
      </div>

      <div className="flex justify-end gap-2">
        <button type="button" onClick={() => navigate("/invoices")} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
        <button type="submit" disabled={isSubmitting}
          className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
          {isSubmitting ? "Saving..." : "Save & Generate Invoice"}
        </button>
      </div>
    </form>
  );
}

export default function NewInvoicePage() {
  return (
    <Suspense fallback={<div className="text-[var(--text-muted)] text-sm">Loading...</div>}>
      <NewInvoiceForm />
    </Suspense>
  );
}

"use client";

import { useMemo } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Invoice } from "@/lib/store";
import { SortableTable } from "@/components/ui/sortable-table";

export default function InvoicesPage() {
  const invoices = useStore((s) => s.invoices);

  const columns = useMemo<ColumnDef<Invoice, unknown>[]>(() => [
    {
      accessorKey: "id", header: "Invoice #",
      cell: ({ row }) => <NavLink href={`/invoices/${row.original.id}`} className="text-[var(--foreground)] hover:underline">{row.original.id}</NavLink>,
    },
    { accessorKey: "customerName", header: "Customer" },
    { accessorKey: "invoiceDate", header: "Date" },
    {
      accessorKey: "totalAmount", header: "Total",
      cell: ({ getValue }) => `Rs. ${(getValue() as number).toLocaleString()}`,
    },
    {
      id: "items", header: "Items", enableSorting: false,
      cell: ({ row }) => `${row.original.items.length} line${row.original.items.length === 1 ? "" : "s"}`,
    },
  ], []);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Invoices</h1>
        <NavLink href="/invoices/new" className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + New Invoice
        </NavLink>
      </div>
      <p className="text-xs text-[var(--text-faint)]">
        Invoices no longer carry a Paid / Unpaid / Partial status. Payment tracking happens on each customer&apos;s ledger - open a customer to record or review payments.
      </p>
      <SortableTable data={invoices} columns={columns} globalFilterPlaceholder="Search invoices..." />
    </div>
  );
}

import type { ReactNode } from "react";
import { AppSidebar } from "@/components/ui/sidebar-component";
import { Topbar } from "@/components/ui/topbar";
import { SidebarProvider } from "@/lib/sidebar-context";
import { NavigationLoadingProvider } from "@/lib/navigation-loading-context";
import { NavigationLoadingOverlay } from "@/components/ui/navigation-loading-overlay";

export default function DashboardLayout({ children }: { children: ReactNode }) {
  return (
    <NavigationLoadingProvider>
      <SidebarProvider>
        <div className="flex min-h-screen bg-[var(--background)]">
          <AppSidebar />
          <div className="flex-1 flex flex-col min-w-0">
            <Topbar />
            <main className="flex-1 p-4 sm:p-6 overflow-y-auto overflow-x-hidden text-[var(--foreground)]">
              {children}
            </main>
          </div>
        </div>
        <NavigationLoadingOverlay />
      </SidebarProvider>
    </NavigationLoadingProvider>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type CartonConfiguration } from "@/lib/store";
import { cartonConfigSchema, type CartonConfigFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";
import { InfoTip } from "@/components/ui/info-tip";

function StatusBadge({ used }: { used: boolean }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
      used ? "bg-amber-950 text-amber-400 border border-amber-900" : "bg-green-950 text-green-400 border border-green-900"
    }`}>
      {used ? "Used in Packing Run" : "Available"}
    </span>
  );
}

function AddConfigDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const addCartonConfiguration = useStore((s) => s.addCartonConfiguration);

  // Packaging cost build-up (BRS v1.2 sec 1.1; Frontend spec v2.2 sec 5.13
  // "Carton Configuration cost preview"). Grams-per-unit is always in
  // grams; the underlying Raw Material's avgUnitCost is per its stock
  // `unit`. Assume that unit is "kg" unless it is literally "g".
  const costPerGram = (rawMaterialId: string) => {
    const rm = rawMaterials.find((r) => r.id === rawMaterialId);
    if (!rm) return 0;
    return rm.unit === "g" ? rm.avgUnitCost : rm.avgUnitCost / 1000;
  };

  const { register, handleSubmit, control, watch, reset, formState: { errors, isSubmitting } } = useForm<CartonConfigFormValues>({
    resolver: zodResolver(cartonConfigSchema),
    defaultValues: { name: "", wrapperId: wrappers[0]?.id ?? "", packetsPerBox: 12, boxId: boxes[0]?.id ?? "", boxesPerCarton: 4 },
  });

  const name = watch("name");
  const wrapperId = watch("wrapperId");
  const boxId = watch("boxId");
  const packetsPerBox = watch("packetsPerBox");
  const boxesPerCarton = watch("boxesPerCarton");

  if (!open) return null;

  const totalPacketsPerCarton = (Number(packetsPerBox) || 0) * (Number(boxesPerCarton) || 0);

  const selectedWrapper = wrappers.find((w) => w.id === wrapperId);
  const selectedBox = boxes.find((b) => b.id === boxId);
  const costPerWrapper = selectedWrapper ? selectedWrapper.gramsPerUnit * costPerGram(selectedWrapper.rawMaterialId) : 0;
  const costPerBox = selectedBox ? selectedBox.gramsPerUnit * costPerGram(selectedBox.rawMaterialId) : 0;
  const costPerPacket = costPerWrapper;
  const costPerBoxAssembled = costPerBox + (Number(packetsPerBox) || 0) * costPerWrapper;
  const costPerCarton = (Number(boxesPerCarton) || 0) * costPerBoxAssembled;

  const onSubmit = async (values: CartonConfigFormValues) => {
    addCartonConfiguration(values);
    toast.success("Carton configuration created");
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">New Carton Configuration</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Configuration Name</label>
            <input {...register("name")} type="text" placeholder='e.g. "Carton A" or "Rs.5 Nimko 48pk"'
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Wrapper</label>
            <Controller
              control={control}
              name="wrapperId"
              render={({ field }) => (
                <select {...field}
                  className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                  <option value="">Select wrapper...</option>
                  {wrappers.map((w) => <option key={w.id} value={w.id}>{w.name}</option>)}
                </select>
              )}
            />
            {errors.wrapperId && <p className="text-xs text-red-400 mt-1">{errors.wrapperId.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Packets per Box</label>
            <input {...register("packetsPerBox")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.packetsPerBox && <p className="text-xs text-red-400 mt-1">{errors.packetsPerBox.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Box</label>
            <Controller
              control={control}
              name="boxId"
              render={({ field }) => (
                <select {...field}
                  className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                  <option value="">Select box...</option>
                  {boxes.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
                </select>
              )}
            />
            {errors.boxId && <p className="text-xs text-red-400 mt-1">{errors.boxId.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Boxes per Carton</label>
            <input {...register("boxesPerCarton")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.boxesPerCarton && <p className="text-xs text-red-400 mt-1">{errors.boxesPerCarton.message}</p>}
          </div>

          {wrapperId && boxId && totalPacketsPerCarton > 0 && (
            <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-3 text-xs text-[var(--text-muted)]">
              {name?.trim() ? <span className="text-[var(--foreground)] font-medium">"{name.trim()}"</span> : "This configuration"} yields{" "}
              <span className="text-[var(--foreground)] font-medium">{totalPacketsPerCarton} packets</span> per carton.
            </div>
          )}

          {wrapperId && boxId && totalPacketsPerCarton > 0 && (
            <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-3 text-xs text-[var(--text-muted)] space-y-1.5">
              <div className="flex items-center text-[var(--foreground)] font-medium">
                Cost Build-Up
                <InfoTip text="Derived from each Wrapper/Box's grams-per-unit x its raw material's current weighted-average cost. Wrapper cost = per packet. Box cost + (Packets/Box x Wrapper cost) = per box. That x Boxes/Carton = per carton. Excludes bulk product cost, which varies per batch." />
              </div>
              <div className="grid grid-cols-2 gap-x-3 gap-y-1">
                <span>Cost / Wrapper (Packet)</span><span className="text-right text-[var(--foreground)]">Rs. {costPerPacket.toFixed(2)}</span>
                <span>Cost / Box</span><span className="text-right text-[var(--foreground)]">Rs. {costPerBox.toFixed(2)}</span>
                <span>Cost / Box (assembled)</span><span className="text-right text-[var(--foreground)]">Rs. {costPerBoxAssembled.toFixed(2)}</span>
                <span className="font-medium">Cost / Carton</span><span className="text-right text-[var(--foreground)] font-medium">Rs. {costPerCarton.toFixed(2)}</span>
              </div>
            </div>
          )}
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function CartonConfigPage() {
  const configs = useStore((s) => s.cartonConfigurations);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const [dialogOpen, setDialogOpen] = useState(false);

  type Row = CartonConfiguration & { wrapperName: string; boxName: string; packetsPerCarton: number };

  const rows = useMemo<Row[]>(() => {
    return configs.map((c) => {
      const wrapper = wrappers.find((w) => w.id === c.wrapperId);
      const box = boxes.find((b) => b.id === c.boxId);
      return {
        ...c,
        wrapperName: wrapper?.name ?? "Unknown Wrapper",
        boxName: box?.name ?? "Unknown Box",
        packetsPerCarton: c.packetsPerBox * c.boxesPerCarton,
      };
    });
  }, [configs, wrappers, boxes]);

  const columns = useMemo<ColumnDef<Row, unknown>[]>(() => [
    { accessorKey: "name", header: "Name", cell: ({ getValue }) => <span className="text-[var(--foreground)] font-medium">{getValue() as string}</span> },
    { accessorKey: "wrapperName", header: "Wrapper" },
    { accessorKey: "packetsPerBox", header: "Packets / Box" },
    { accessorKey: "boxName", header: "Box" },
    { accessorKey: "boxesPerCarton", header: "Boxes / Carton" },
    { accessorKey: "packetsPerCarton", header: "Packets / Carton" },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge used={row.original.usedInPackingRun} />,
    },
  ], []);

  const canCreate = wrappers.length > 0 && boxes.length > 0;

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <a href="/packaging" className="hover:underline text-[var(--text-secondary)]">Packaging Materials</a>{" "}
        / <span className="text-[var(--foreground)]">Carton Configurations</span>
      </div>

      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Carton Configurations</h1>
        <button
          onClick={() => setDialogOpen(true)}
          disabled={!canCreate}
          title={canCreate ? undefined : "Add at least one Wrapper and one Box first"}
          className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50"
        >
          + New Configuration
        </button>
      </div>

      {!canCreate && (
        <div className="rounded-xl border border-amber-900 bg-amber-950 p-4 text-sm text-amber-400">
          You need at least one Wrapper and one Box before creating a carton configuration.
        </div>
      )}

      <SortableTable data={rows} columns={columns} globalFilterPlaceholder="Search configurations..." />
      <AddConfigDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Wrapper, type Box, type RawMaterial } from "@/lib/store";
import {
  wrapperDefinitionSchema,
  boxDefinitionSchema,
  productionRunSchema,
  type WrapperDefinitionFormValues,
  type BoxDefinitionFormValues,
  type ProductionRunFormValues,
} from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function StatusBadge({ isLow }: { isLow: boolean }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
      isLow ? "bg-red-950 text-red-400 border border-red-900" : "bg-green-950 text-green-400 border border-green-900"
    }`}>
      {isLow ? "Low Stock" : "OK"}
    </span>
  );
}

function InfoTip({ text }: { text: string }) {
  return (
    <span
      title={text}
      className="ml-1 inline-flex h-4 w-4 items-center justify-center rounded-full border border-[var(--surface-border-strong)] text-[10px] leading-none text-[var(--text-muted)] cursor-help select-none align-middle"
    >
      i
    </span>
  );
}

type PackagingKind = "wrapper" | "box";

function DefineDialog({ kind, open, onClose }: { kind: PackagingKind; open: boolean; onClose: () => void }) {
  const rawMaterials = useStore((s) => s.rawMaterials);
  const addWrapper = useStore((s) => s.addWrapper);
  const addBox = useStore((s) => s.addBox);
  const schema = kind === "wrapper" ? wrapperDefinitionSchema : boxDefinitionSchema;

  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm<
    WrapperDefinitionFormValues | BoxDefinitionFormValues
  >({
    resolver: zodResolver(schema),
    defaultValues: {
      name: "",
      rawMaterialId: rawMaterials[0]?.id ?? "",
      gramsPerUnit: 0,
      lowStockThreshold: kind === "wrapper" ? 500 : 100,
    },
  });

  if (!open) return null;
  const label = kind === "wrapper" ? "Wrapper" : "Box";

  const onSubmit = async (values: WrapperDefinitionFormValues) => {
    if (kind === "wrapper") addWrapper(values);
    else addBox(values);
    toast.success(`${label} "${values.name}" defined`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Define {label}</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Name</label>
            <input {...register("name")} placeholder={kind === "wrapper" ? "e.g. Rs. 5 Wrapper" : "e.g. Box (12 packets)"}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Underlying Raw Material</label>
            <select {...register("rawMaterialId")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
              {rawMaterials.map((m: RawMaterial) => (
                <option key={m.id} value={m.id}>{m.name} ({m.unit})</option>
              ))}
            </select>
            {errors.rawMaterialId && <p className="text-xs text-red-400 mt-1">{errors.rawMaterialId.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)] inline-flex items-center">
              Grams per Unit
              <InfoTip text={`How many grams of the underlying raw material are used to make one ${label.toLowerCase()}`} />
            </label>
            <input {...register("gramsPerUnit")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.gramsPerUnit && <p className="text-xs text-red-400 mt-1">{errors.gramsPerUnit.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Low Stock Threshold</label>
            <input {...register("lowStockThreshold")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.lowStockThreshold && <p className="text-xs text-red-400 mt-1">{errors.lowStockThreshold.message}</p>}
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

type ProduceTarget = { kind: PackagingKind; item: Wrapper | Box } | null;

function ProduceDialog({ target, onClose }: { target: ProduceTarget; onClose: () => void }) {
  const rawMaterials = useStore((s) => s.rawMaterials);
  const produceWrapper = useStore((s) => s.produceWrapper);
  const produceBox = useStore((s) => s.produceBox);

  const { register, handleSubmit, reset, watch, formState: { errors, isSubmitting } } = useForm<ProductionRunFormValues>({
    resolver: zodResolver(productionRunSchema),
    defaultValues: { quantityProduced: 1 },
  });

  const quantityProducedRaw = watch("quantityProduced");
  const quantityProduced = Number(quantityProducedRaw) || 0;

  if (!target) return null;
  const { kind, item } = target;
  const rawMaterial = rawMaterials.find((m) => m.id === item.rawMaterialId);
  const unit = (rawMaterial?.unit ?? "").trim().toLowerCase();
  const multiplier = unit === "kg" || unit === "kilogram" || unit === "kilograms" ? 1000 : 1;
  const availableGrams = rawMaterial ? rawMaterial.quantityInStock * multiplier : 0;
  const gramsToConsume = item.gramsPerUnit * quantityProduced;
  const insufficient = gramsToConsume > availableGrams;

  const onSubmit = async (values: ProductionRunFormValues) => {
    const result = kind === "wrapper" ? produceWrapper(item.id, values.quantityProduced) : produceBox(item.id, values.quantityProduced);
    if (!result.ok) {
      toast.error(result.reason ?? "Could not complete production run");
      return;
    }
    toast.success(`Produced ${values.quantityProduced} x ${item.name}`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Produce: {item.name}</h2>

        <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-3 space-y-1 text-xs text-[var(--text-muted)]">
          <div className="flex justify-between">
            <span>Grams per Unit</span>
            <span className="text-[var(--foreground)]">{item.gramsPerUnit.toLocaleString()} g</span>
          </div>
          <div className="flex justify-between">
            <span>{rawMaterial?.name ?? "Raw material"} in stock</span>
            <span className="text-[var(--foreground)]">{availableGrams.toLocaleString()} g</span>
          </div>
        </div>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Quantity to Produce</label>
          <input {...register("quantityProduced")} type="number" min={1}
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.quantityProduced && <p className="text-xs text-red-400 mt-1">{errors.quantityProduced.message}</p>}
        </div>

        <div className={`rounded-lg border p-3 text-xs ${insufficient ? "border-red-900 bg-red-950 text-red-400" : "border-[var(--surface-border)] bg-[var(--background)] text-[var(--text-muted)]"}`}>
          <div className="flex justify-between">
            <span>Grams to be consumed</span>
            <span className={insufficient ? "text-red-400 font-medium" : "text-[var(--foreground)] font-medium"}>
              {gramsToConsume.toLocaleString()} g
            </span>
          </div>
          {insufficient && (
            <p className="mt-1">Not enough {rawMaterial?.name ?? "raw material"} in stock to produce this quantity.</p>
          )}
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting || insufficient} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Producing..." : "Confirm"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function PackagingPage() {
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrapperUnitCost = useStore((s) => s.wrapperUnitCost);
  const boxUnitCost = useStore((s) => s.boxUnitCost);

  const [tab, setTab] = useState<"wrappers" | "boxes">("wrappers");
  const [defineOpen, setDefineOpen] = useState<PackagingKind | null>(null);
  const [produceTarget, setProduceTarget] = useState<ProduceTarget>(null);

  const materialName = (id: string) => rawMaterials.find((m) => m.id === id)?.name ?? "-";

  const wrapperColumns = useMemo<ColumnDef<Wrapper, unknown>[]>(() => [
    { accessorKey: "name", header: "Name", cell: ({ getValue }) => <span className="text-[var(--foreground)]">{getValue() as string}</span> },
    { id: "rawMaterial", header: "Underlying Raw Material", cell: ({ row }) => materialName(row.original.rawMaterialId) },
    { accessorKey: "gramsPerUnit", header: "Grams per Unit", cell: ({ getValue }) => `${(getValue() as number).toLocaleString()} g` },
    { id: "unitCost", header: "Derived Unit Cost", cell: ({ row }) => `Rs. ${wrapperUnitCost(row.original.id).toFixed(2)}` },
    { accessorKey: "stockQty", header: "Stock Qty", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    { accessorKey: "lowStockThreshold", header: "Threshold", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge isLow={row.original.stockQty < row.original.lowStockThreshold} />,
    },
    {
      id: "action", header: "", enableSorting: false,
      cell: ({ row }) => (
        <button onClick={() => setProduceTarget({ kind: "wrapper", item: row.original })}
          className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-xs text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
          Produce
        </button>
      ),
    },
  ], [rawMaterials, wrapperUnitCost]);

  const boxColumns = useMemo<ColumnDef<Box, unknown>[]>(() => [
    { accessorKey: "name", header: "Name", cell: ({ getValue }) => <span className="text-[var(--foreground)]">{getValue() as string}</span> },
    { id: "rawMaterial", header: "Underlying Raw Material", cell: ({ row }) => materialName(row.original.rawMaterialId) },
    { accessorKey: "gramsPerUnit", header: "Grams per Unit", cell: ({ getValue }) => `${(getValue() as number).toLocaleString()} g` },
    { id: "unitCost", header: "Derived Unit Cost", cell: ({ row }) => `Rs. ${boxUnitCost(row.original.id).toFixed(2)}` },
    { accessorKey: "stockQty", header: "Stock Qty", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    { accessorKey: "lowStockThreshold", header: "Threshold", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge isLow={row.original.stockQty < row.original.lowStockThreshold} />,
    },
    {
      id: "action", header: "", enableSorting: false,
      cell: ({ row }) => (
        <button onClick={() => setProduceTarget({ kind: "box", item: row.original })}
          className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-xs text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
          Produce
        </button>
      ),
    },
  ], [rawMaterials, boxUnitCost]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Packaging Materials</h1>
        <div className="flex items-center gap-2">
          <NavLink href="/packaging/carton-config" className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
            Define Carton Configuration
          </NavLink>
          {tab === "wrappers" ? (
            <button onClick={() => setDefineOpen("wrapper")} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
              + Define Wrapper
            </button>
          ) : (
            <button onClick={() => setDefineOpen("box")} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
              + Define Box
            </button>
          )}
        </div>
      </div>

      <div className="flex gap-2 border-b border-[var(--surface-border)]">
        <button onClick={() => setTab("wrappers")} className={`px-4 py-2 text-sm font-medium border-b-2 ${tab === "wrappers" ? "border-neutral-900 dark:border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"}`}>
          Wrappers
        </button>
        <button onClick={() => setTab("boxes")} className={`px-4 py-2 text-sm font-medium border-b-2 ${tab === "boxes" ? "border-neutral-900 dark:border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"}`}>
          Boxes
        </button>
      </div>

      {tab === "wrappers" ? (
        <SortableTable data={wrappers} columns={wrapperColumns} globalFilterPlaceholder="Search wrappers..." />
      ) : (
        <SortableTable data={boxes} columns={boxColumns} globalFilterPlaceholder="Search boxes..." />
      )}

      <DefineDialog kind={defineOpen ?? "wrapper"} open={defineOpen !== null} onClose={() => setDefineOpen(null)} />
      <ProduceDialog target={produceTarget} onClose={() => setProduceTarget(null)} />
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useRouter } from "next/navigation";
import { useNavigationLoading } from "@/lib/navigation-loading-context";
import { useStore } from "@/lib/store";

function KpiCard({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="bg-[var(--surface)] border border-[var(--surface-border)] rounded-xl p-4">
      <div className="text-[var(--text-muted)] text-sm">{label}</div>
      <div className="text-2xl font-semibold text-[var(--foreground)] mt-1">{value}</div>
    </div>
  );
}

export default function DashboardPage() {
  const router = useRouter();
  const { navigate } = useNavigationLoading();
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const invoices = useStore((s) => s.invoices);
  const finishedCartons = useStore((s) => s.finishedCartons);
  const customers = useStore((s) => s.customers);

  const lowStockItems = useMemo(() => {
    const rawAlerts = rawMaterials
      .filter((m) => m.quantityInStock < m.lowStockThreshold)
      .map((m) => ({ id: m.id, name: m.name, href: `/raw-materials/${m.id}`, qty: m.quantityInStock, threshold: m.lowStockThreshold }));
    const wrapperAlerts = wrappers
      .filter((w) => w.stockQty < w.lowStockThreshold)
      .map((w) => ({ id: w.id, name: w.name, href: `/packaging`, qty: w.stockQty, threshold: w.lowStockThreshold }));
    const boxAlerts = boxes
      .filter((b) => b.stockQty < b.lowStockThreshold)
      .map((b) => ({ id: b.id, name: b.name, href: `/packaging`, qty: b.stockQty, threshold: b.lowStockThreshold }));
    return [...rawAlerts, ...wrapperAlerts, ...boxAlerts];
  }, [rawMaterials, wrappers, boxes]);

  const kpis = useMemo(() => {
    const totalRawMaterialValue = rawMaterials.reduce((sum, m) => sum + m.quantityInStock * m.avgUnitCost, 0);
    const finishedCartonsReady = finishedCartons.reduce((sum, c) => sum + c.stockQty, 0);
    const totalReceivables = customers.reduce((sum, c) => sum + Math.max(0, c.currentBalance), 0);
    return { totalRawMaterialValue, finishedCartonsReady, totalReceivables };
  }, [rawMaterials, finishedCartons, customers]);

  const recentInvoices = invoices.slice(0, 5);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold">Dashboard</h1>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard label="Total Raw Material Value" value={`Rs. ${kpis.totalRawMaterialValue.toLocaleString(undefined, { maximumFractionDigits: 0 })}`} />
        <KpiCard label="Batches This Month" value={6} />
        <KpiCard label="Finished Cartons Ready" value={kpis.finishedCartonsReady} />
        <KpiCard label="Total Receivables" value={`Rs. ${kpis.totalReceivables.toLocaleString()}`} />
      </div>

      <div className="flex flex-wrap gap-2">
        <NavLink href="/raw-materials" className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)] transition-colors">
          + Add Raw Material
        </NavLink>
        <button onClick={() => navigate("/batches/new")} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)] transition-colors">
          + New Batch
        </button>
        <button onClick={() => navigate("/invoices/new")} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + New Invoice
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] overflow-hidden">
          <div className="px-4 py-3 border-b border-[var(--surface-border)]">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Low Stock Alerts</h2>
          </div>
          <div className="divide-y divide-[var(--surface-border)]">
            {lowStockItems.length === 0 && (
              <div className="px-4 py-6 text-center text-sm text-[var(--text-faint)]">All stock levels are healthy.</div>
            )}
            {lowStockItems.map((item) => (
              <NavLink key={item.id} href={item.href} className="flex items-center justify-between px-4 py-3 hover:bg-[var(--surface-hover)]/60">
                <span className="text-sm text-[var(--foreground)]">{item.name}</span>
                <span className="text-xs text-red-400">{item.qty} / {item.threshold}</span>
              </NavLink>
            ))}
          </div>
        </div>

        <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] overflow-hidden">
          <div className="px-4 py-3 border-b border-[var(--surface-border)] flex items-center justify-between">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Recent Invoices</h2>
            <NavLink href="/invoices" className="text-xs text-[var(--text-muted)] hover:text-[var(--foreground)] hover:underline">View all</NavLink>
          </div>
          <table className="w-full text-sm">
            <tbody>
              {recentInvoices.map((inv) => (
                <tr key={inv.id} className="border-b border-[var(--surface-border)] last:border-0">
                  <td className="px-4 py-3">
                    <NavLink href={`/invoices/${inv.id}`} className="text-[var(--foreground)] hover:underline">{inv.id}</NavLink>
                  </td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{inv.customerName}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {inv.totalAmount.toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Payment } from "@/lib/store";
import { paymentSchema, type PaymentFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function RecordPaymentDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const customers = useStore((s) => s.customers);
  const recordLedgerEntry = useStore((s) => s.recordLedgerEntry);
  const {
    register,
    handleSubmit,
    reset,
    watch,
    setValue,
    formState: { errors, isSubmitting },
  } = useForm<PaymentFormValues>({
    resolver: zodResolver(paymentSchema),
    defaultValues: { customerId: customers[0]?.id ?? "", amount: 0, direction: "received", note: "" },
  });
  const direction = watch("direction");

  if (!open) return null;

  const onSubmit = async (values: PaymentFormValues) => {
    recordLedgerEntry(values.customerId, values.amount, values.direction, values.note ?? "");
    toast.success(
      values.direction === "received"
        ? `Payment of Rs. ${values.amount.toLocaleString()} received`
        : `Rs. ${values.amount.toLocaleString()} recorded as given / credit adjustment`
    );
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Record Payment</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Customer</label>
            <select {...register("customerId")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
              {customers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            {errors.customerId && <p className="text-xs text-red-400 mt-1">{errors.customerId.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Amount</label>
            <input {...register("amount")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.amount && <p className="text-xs text-red-400 mt-1">{errors.amount.message}</p>}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <label className="text-sm text-[var(--text-muted)]">Direction</label>
              <span
                title='Received = payment received from customer, reduces what they owe. Given = amount given to customer (refund) or a credit adjustment in their favor.'
                className="flex h-3.5 w-3.5 cursor-help items-center justify-center rounded-full border border-[var(--text-faint)] text-[9px] leading-none text-[var(--text-faint)]"
              >
                i
              </span>
            </div>
            <div className="mt-1 grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setValue("direction", "received", { shouldValidate: true })}
                className={`rounded-lg border px-3 py-2 text-xs font-medium transition-colors ${
                  direction === "received"
                    ? "border-green-500 bg-green-500/10 text-green-400"
                    : "border-[var(--surface-border)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                }`}
              >
                + Received from customer
              </button>
              <button
                type="button"
                onClick={() => setValue("direction", "given", { shouldValidate: true })}
                className={`rounded-lg border px-3 py-2 text-xs font-medium transition-colors ${
                  direction === "given"
                    ? "border-red-500 bg-red-500/10 text-red-400"
                    : "border-[var(--surface-border)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                }`}
              >
                âˆ’ Given / credit adjustment
              </button>
            </div>
            <input type="hidden" {...register("direction")} />
            {errors.direction && <p className="text-xs text-red-400 mt-1">{errors.direction.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Note</label>
            <input {...register("note")} placeholder='e.g. "cash refund", "damaged stock credit"'
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function PaymentsPage() {
  const items = useStore((s) => s.payments);
  const [dialogOpen, setDialogOpen] = useState(false);

  const columns = useMemo<ColumnDef<Payment, unknown>[]>(() => [
    { accessorKey: "paidAt", header: "Date" },
    { accessorKey: "customerName", header: "Customer", cell: ({ getValue }) => <span className="text-[var(--foreground)]">{getValue() as string}</span> },
    {
      accessorKey: "direction", header: "Direction",
      cell: ({ getValue }) => {
        const dir = getValue() as Payment["direction"];
        return dir === "received" ? (
          <span className="rounded-full bg-green-500/10 px-2 py-0.5 text-xs font-medium text-green-400">+ Received</span>
        ) : (
          <span className="rounded-full bg-red-500/10 px-2 py-0.5 text-xs font-medium text-red-400">âˆ’ Given</span>
        );
      },
    },
    {
      accessorKey: "amount", header: "Amount",
      cell: ({ row }) => (
        <span className={row.original.direction === "received" ? "text-green-400" : "text-red-400"}>
          {row.original.direction === "received" ? "+" : "âˆ’"} Rs. {(row.original.amount as number).toLocaleString()}
        </span>
      ),
    },
    { accessorKey: "note", header: "Note" },
  ], []);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Payments</h1>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Record Payment
        </button>
      </div>
      <SortableTable data={items} columns={columns} globalFilterPlaceholder="Search payments..." />
      <RecordPaymentDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

"use client";

import { use, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useStore } from "@/lib/store";
import { PurchaseReceiptDialog } from "@/components/ui/purchase-receipt-dialog";

export default function RawMaterialDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const material = useStore((s) => s.rawMaterials.find((m) => m.id === id));
  const receipts = useStore((s) => s.receipts);
  const receiptLines = useStore((s) => s.receiptLines);
  const suppliers = useStore((s) => s.suppliers);
  const [dialogOpen, setDialogOpen] = useState(false);

  const history = useMemo(() => {
    return receiptLines
      .filter((rl) => rl.rawMaterialId === id)
      .map((rl) => {
        const receipt = receipts.find((r) => r.id === rl.receiptId);
        const supplier = receipt ? suppliers.find((s) => s.id === receipt.supplierId) : undefined;
        return {
          id: rl.id,
          date: receipt?.purchaseDate ?? "-",
          supplier,
          receiptId: rl.receiptId,
          qty: rl.qty,
          cost: rl.cost,
        };
      })
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [receiptLines, receipts, suppliers, id]);

  if (!material) {
    return (
      <div className="space-y-4">
        <NavLink href="/raw-materials" className="text-sm text-[var(--text-muted)] hover:underline">&larr; Back to Raw Materials</NavLink>
        <p className="text-[var(--text-muted)]">Raw material not found.</p>
      </div>
    );
  }

  const isLow = material.quantityInStock < material.lowStockThreshold;

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <NavLink href="/raw-materials" className="hover:underline text-[var(--text-secondary)]">Raw Materials</NavLink>{" "}
        / <span className="text-[var(--foreground)]">{material.name}</span>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-xl font-semibold text-[var(--foreground)]">{material.name}</h1>
            <p className="text-sm text-[var(--text-muted)] mt-1">Unit: {material.unit}</p>
          </div>
          <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
            isLow ? "bg-red-950 text-red-400 border border-red-900" : "bg-green-950 text-green-400 border border-green-900"
          }`}>
            {isLow ? "Low Stock" : "OK"}
          </span>
        </div>

        <div className="mt-5 grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div>
            <div className="text-[var(--text-muted)] text-xs">Current Stock</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{material.quantityInStock} {material.unit}</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs flex items-center gap-1">
              Avg Unit Cost
              <span title="Weighted average: (Existing Qty x Existing Avg Cost + New Qty x New Cost) / (Existing Qty + New Qty)" className="cursor-help text-[var(--text-faint)]">(i)</span>
            </div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">Rs. {material.avgUnitCost.toLocaleString()}</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Low Stock Threshold</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{material.lowStockThreshold}</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Stock Value</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">Rs. {(material.quantityInStock * material.avgUnitCost).toLocaleString()}</div>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Purchase History</h2>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Record Purchase
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium">Date</th>
              <th className="px-4 py-3 font-medium">Supplier</th>
              <th className="px-4 py-3 font-medium">Quantity</th>
              <th className="px-4 py-3 font-medium">Cost / Unit</th>
              <th className="px-4 py-3 font-medium">Total</th>
              <th className="px-4 py-3 font-medium">Receipt</th>
            </tr>
          </thead>
          <tbody>
            {history.map((h) => (
              <tr key={h.id} className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                <td className="px-4 py-3 text-[var(--text-secondary)]">{h.date}</td>
                <td className="px-4 py-3 text-[var(--text-secondary)]">
                  {h.supplier ? (
                    <NavLink href={`/suppliers/${h.supplier.id}`} className="hover:underline text-[var(--foreground)]">{h.supplier.name}</NavLink>
                  ) : "-"}
                </td>
                <td className="px-4 py-3 text-[var(--text-secondary)]">{h.qty} {material.unit}</td>
                <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {h.cost.toLocaleString()}</td>
                <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {(h.qty * h.cost).toLocaleString()}</td>
                <td className="px-4 py-3 text-[var(--text-secondary)]">
                  <NavLink href={`/receipts`} className="hover:underline text-[var(--foreground)]">{h.receiptId}</NavLink>
                </td>
              </tr>
            ))}
            {history.length === 0 && (
              <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--text-faint)]">No purchases recorded yet.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <PurchaseReceiptDialog open={dialogOpen} onClose={() => setDialogOpen(false)} lockRawMaterialId={material.id} />
    </div>
  );
}

"use client";

import { Fragment, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { ChevronDown, ChevronRight } from "lucide-react";
import { useStore } from "@/lib/store";
import { rawMaterialMasterSchema, type RawMaterialMasterFormValues } from "@/lib/schemas";
import { PurchaseReceiptDialog } from "@/components/ui/purchase-receipt-dialog";
import { InfoTip } from "@/components/ui/info-tip";

function StatusBadge({ isLow }: { isLow: boolean }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
      isLow ? "bg-red-950 text-red-400 border border-red-900" : "bg-green-950 text-green-400 border border-green-900"
    }`}>
      {isLow ? "Low Stock" : "OK"}
    </span>
  );
}

function AddRawMaterialMasterDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const addRawMaterial = useStore((s) => s.addRawMaterial);
  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm<RawMaterialMasterFormValues>({
    resolver: zodResolver(rawMaterialMasterSchema),
    defaultValues: { name: "", unit: "kg", lowStockThreshold: 50 },
  });

  if (!open) return null;

  const onSubmit = async (values: RawMaterialMasterFormValues) => {
    addRawMaterial(values);
    toast.success(`Raw material "${values.name}" added - record a purchase to add stock`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Add Raw Material</h2>
        <p className="text-xs text-[var(--text-faint)]">
          Creates the master record only (name, unit, threshold). Stock and cost come from
          purchase receipts - use "Record Purchase" to add stock.
        </p>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Name</label>
            <input {...register("name")} placeholder="e.g. Atta (Flour)"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Unit</label>
            <input {...register("unit")} placeholder="kg, g, litre..."
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.unit && <p className="text-xs text-red-400 mt-1">{errors.unit.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Low Stock Threshold</label>
            <input {...register("lowStockThreshold")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.lowStockThreshold && <p className="text-xs text-red-400 mt-1">{errors.lowStockThreshold.message}</p>}
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function RawMaterialsPage() {
  const rawMaterials = useStore((s) => s.rawMaterials);
  const receipts = useStore((s) => s.receipts);
  const receiptLines = useStore((s) => s.receiptLines);
  const suppliers = useStore((s) => s.suppliers);

  const [search, setSearch] = useState("");
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [addOpen, setAddOpen] = useState(false);
  const [receiptOpen, setReceiptOpen] = useState(false);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return rawMaterials;
    return rawMaterials.filter((m) => m.name.toLowerCase().includes(q) || m.unit.toLowerCase().includes(q));
  }, [rawMaterials, search]);

  const historyFor = (materialId: string) => {
    return receiptLines
      .filter((rl) => rl.rawMaterialId === materialId)
      .map((rl) => {
        const receipt = receipts.find((r) => r.id === rl.receiptId);
        const supplier = receipt ? suppliers.find((s) => s.id === receipt.supplierId) : undefined;
        return {
          id: rl.id,
          date: receipt?.purchaseDate ?? "-",
          supplierName: supplier?.name ?? "-",
          supplierId: supplier?.id,
          qty: rl.qty,
          cost: rl.cost,
        };
      })
      .sort((a, b) => b.date.localeCompare(a.date));
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Raw Materials</h1>
        <div className="flex items-center gap-2">
          <button onClick={() => setAddOpen(true)} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
            + Add Raw Material
          </button>
          <button onClick={() => setReceiptOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
            + Record Purchase
          </button>
        </div>
      </div>

      <input
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        placeholder="Search raw materials..."
        className="w-full max-w-sm rounded-lg border border-[var(--surface-border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--foreground)] placeholder:text-[var(--text-faint)] outline-none focus:border-[var(--surface-border-strong)]"
      />

      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full min-w-[720px] text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium w-8"></th>
              <th className="px-4 py-3 font-medium">Name</th>
              <th className="px-4 py-3 font-medium">Unit</th>
              <th className="px-4 py-3 font-medium">Qty in Stock</th>
              <th className="px-4 py-3 font-medium">
                <span className="inline-flex items-center">
                  Avg Unit Cost
                  <InfoTip text="Weighted average cost per unit across all purchase receipts for this raw material, recalculated on every new receipt." />
                </span>
              </th>
              <th className="px-4 py-3 font-medium">Threshold</th>
              <th className="px-4 py-3 font-medium">Status</th>
            </tr>
          </thead>
          <tbody>
            {filtered.length === 0 && (
              <tr><td colSpan={7} className="px-4 py-8 text-center text-[var(--text-faint)]">No raw materials found.</td></tr>
            )}
            {filtered.map((m) => {
              const isLow = m.quantityInStock < m.lowStockThreshold;
              const isExpanded = expandedId === m.id;
              const history = isExpanded ? historyFor(m.id) : [];
              return (
                <Fragment key={m.id}>
                  <tr className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => setExpandedId(isExpanded ? null : m.id)}
                        className="text-[var(--text-muted)] hover:text-[var(--foreground)]"
                        aria-label={isExpanded ? "Collapse" : "Expand"}
                      >
                        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                      </button>
                    </td>
                    <td className="px-4 py-3">
                      <NavLink href={`/raw-materials/${m.id}`} className="text-[var(--foreground)] hover:underline">
                        {m.name}
                      </NavLink>
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{m.unit}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{m.quantityInStock}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {m.avgUnitCost.toLocaleString()}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{m.lowStockThreshold}</td>
                    <td className="px-4 py-3"><StatusBadge isLow={isLow} /></td>
                  </tr>
                  {isExpanded && (
                    <tr className="border-b border-[var(--surface-border)] last:border-0 bg-[var(--background)]">
                      <td></td>
                      <td colSpan={6} className="px-4 py-3">
                        {history.length === 0 ? (
                          <p className="text-xs text-[var(--text-faint)] py-2">No purchase history yet for this material.</p>
                        ) : (
                          <table className="w-full text-xs">
                            <thead>
                              <tr className="text-left text-[var(--text-muted)]">
                                <th className="pb-2 font-medium">Date</th>
                                <th className="pb-2 font-medium">Supplier</th>
                                <th className="pb-2 font-medium">Quantity</th>
                                <th className="pb-2 font-medium">Cost/Unit</th>
                                <th className="pb-2 font-medium">Total</th>
                              </tr>
                            </thead>
                            <tbody>
                              {history.map((h) => (
                                <tr key={h.id} className="border-t border-[var(--surface-border)]">
                                  <td className="py-2 text-[var(--text-secondary)]">{h.date}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">
                                    {h.supplierId ? (
                                      <NavLink href={`/suppliers/${h.supplierId}`} className="hover:underline text-[var(--foreground)]">{h.supplierName}</NavLink>
                                    ) : h.supplierName}
                                  </td>
                                  <td className="py-2 text-[var(--text-secondary)]">{h.qty} {m.unit}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {h.cost.toLocaleString()}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {(h.qty * h.cost).toLocaleString()}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        )}
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      </div>

      <AddRawMaterialMasterDialog open={addOpen} onClose={() => setAddOpen(false)} />
      <PurchaseReceiptDialog open={receiptOpen} onClose={() => setReceiptOpen(false)} />
    </div>
  );
}

"use client";

import { Fragment, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { ChevronDown, ChevronRight } from "lucide-react";
import { useStore } from "@/lib/store";
import { PurchaseReceiptDialog } from "@/components/ui/purchase-receipt-dialog";

export default function ReceiptsPage() {
  const receipts = useStore((s) => s.receipts);
  const receiptLines = useStore((s) => s.receiptLines);
  const suppliers = useStore((s) => s.suppliers);
  const rawMaterials = useStore((s) => s.rawMaterials);

  const [supplierFilter, setSupplierFilter] = useState("");
  const [materialFilter, setMaterialFilter] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  const rows = useMemo(() => {
    return receipts
      .map((r) => {
        const lines = receiptLines.filter((l) => l.receiptId === r.id);
        const supplier = suppliers.find((s) => s.id === r.supplierId);
        const totalValue = lines.reduce((sum, l) => sum + l.qty * l.cost, 0);
        const itemNames = lines.map((l) => rawMaterials.find((m) => m.id === l.rawMaterialId)?.name ?? "?");
        return { receipt: r, lines, supplier, totalValue, itemNames };
      })
      .filter(({ receipt, lines }) => {
        if (supplierFilter && receipt.supplierId !== supplierFilter) return false;
        if (materialFilter && !lines.some((l) => l.rawMaterialId === materialFilter)) return false;
        if (fromDate && receipt.purchaseDate < fromDate) return false;
        if (toDate && receipt.purchaseDate > toDate) return false;
        return true;
      })
      .sort((a, b) => b.receipt.purchaseDate.localeCompare(a.receipt.purchaseDate));
  }, [receipts, receiptLines, suppliers, rawMaterials, supplierFilter, materialFilter, fromDate, toDate]);

  const hasFilters = !!(supplierFilter || materialFilter || fromDate || toDate);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Receipts</h1>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Record Purchase
        </button>
      </div>

      <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-end gap-3 rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
        <div>
          <label className="text-xs text-[var(--text-muted)]">Supplier</label>
          <select value={supplierFilter} onChange={(e) => setSupplierFilter(e.target.value)}
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
            <option value="">All suppliers</option>
            {suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">Raw Material</label>
          <select value={materialFilter} onChange={(e) => setMaterialFilter(e.target.value)}
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
            <option value="">All materials</option>
            {rawMaterials.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">From</label>
          <input value={fromDate} onChange={(e) => setFromDate(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">To</label>
          <input value={toDate} onChange={(e) => setToDate(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
        {hasFilters && (
          <button
            type="button"
            onClick={() => { setSupplierFilter(""); setMaterialFilter(""); setFromDate(""); setToDate(""); }}
            className="rounded-lg px-3 py-2 text-xs text-[var(--text-muted)] hover:bg-[var(--surface-hover)]"
          >
            Clear filters
          </button>
        )}
      </div>

      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full min-w-[640px] text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium w-8"></th>
              <th className="px-4 py-3 font-medium">Receipt Date</th>
              <th className="px-4 py-3 font-medium">Supplier</th>
              <th className="px-4 py-3 font-medium">Items</th>
              <th className="px-4 py-3 font-medium">Total Value</th>
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[var(--text-faint)]">No receipts match these filters.</td></tr>
            )}
            {rows.map(({ receipt, lines, supplier, totalValue, itemNames }) => {
              const isExpanded = expandedId === receipt.id;
              const summary = itemNames.length > 2
                ? `${itemNames.length} items: ${itemNames.slice(0, 2).join(", ")}, +${itemNames.length - 2}`
                : `${itemNames.length} item${itemNames.length !== 1 ? "s" : ""}: ${itemNames.join(", ")}`;
              return (
                <Fragment key={receipt.id}>
                  <tr className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                    <td className="px-4 py-3">
                      <button type="button" onClick={() => setExpandedId(isExpanded ? null : receipt.id)} className="text-[var(--text-muted)] hover:text-[var(--foreground)]">
                        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                      </button>
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{receipt.purchaseDate}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">
                      {supplier ? (
                        <NavLink href={`/suppliers/${supplier.id}`} className="hover:underline text-[var(--foreground)]">{supplier.name}</NavLink>
                      ) : "-"}
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{summary}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {totalValue.toLocaleString()}</td>
                  </tr>
                  {isExpanded && (
                    <tr className="border-b border-[var(--surface-border)] last:border-0 bg-[var(--background)]">
                      <td></td>
                      <td colSpan={4} className="px-4 py-3">
                        <table className="w-full text-xs">
                          <thead>
                            <tr className="text-left text-[var(--text-muted)]">
                              <th className="pb-2 font-medium">Raw Material</th>
                              <th className="pb-2 font-medium">Quantity</th>
                              <th className="pb-2 font-medium">Cost/Unit</th>
                              <th className="pb-2 font-medium">Total</th>
                            </tr>
                          </thead>
                          <tbody>
                            {lines.map((l) => {
                              const material = rawMaterials.find((m) => m.id === l.rawMaterialId);
                              return (
                                <tr key={l.id} className="border-t border-[var(--surface-border)]">
                                  <td className="py-2 text-[var(--text-secondary)]">
                                    {material ? (
                                      <NavLink href={`/raw-materials/${material.id}`} className="hover:underline text-[var(--foreground)]">{material.name}</NavLink>
                                    ) : "-"}
                                  </td>
                                  <td className="py-2 text-[var(--text-secondary)]">{l.qty} {material?.unit ?? ""}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {l.cost.toLocaleString()}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {(l.qty * l.cost).toLocaleString()}</td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      </div>

      <PurchaseReceiptDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer, Legend,
} from "recharts";
import { useStore } from "@/lib/store";

function exportCSV(filename: string, headers: string[], rows: (string | number)[][]) {
  const lines = [headers.join(","), ...rows.map((r) => r.map((v) => `"${v}"`).join(","))];
  const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export default function ReportsPage() {
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const productionBatches = useStore((s) => s.productionBatches);
  const invoices = useStore((s) => s.invoices);
  const finishedCartons = useStore((s) => s.finishedCartons);

  const [tab, setTab] = useState<"inventory" | "yield" | "pnl">("inventory");
  const [from, setFrom] = useState("2026-08-01");
  const [to, setTo] = useState("2026-08-18");

  const inventoryData = useMemo(() => [
    ...rawMaterials.map((m) => ({ name: m.name, stock: m.quantityInStock, threshold: m.lowStockThreshold, type: "Raw" })),
    ...wrappers.map((w) => ({ name: w.name, stock: w.stockQty, threshold: w.lowStockThreshold, type: "Wrapper" })),
    ...boxes.map((b) => ({ name: b.name, stock: b.stockQty, threshold: b.lowStockThreshold, type: "Box" })),
  ], [rawMaterials, wrappers, boxes]);

  const yieldData = useMemo(() =>
    productionBatches.map((b) => ({
      batch: b.id,
      outputYield: b.outputYieldKg,
      wastage: b.wastageKg,
      leftover: b.leftoverQtyKg,
    })), [productionBatches]);

  const pnl = useMemo(() => {
    const filteredInvoices = invoices.filter((i) => i.invoiceDate >= from && i.invoiceDate <= to);
    const filteredBatches = productionBatches.filter((b) => b.batchDate >= from && b.batchDate <= to);
    const totalRevenue = filteredInvoices.reduce((sum, i) => sum + i.totalAmount, 0);
    const totalCost = filteredBatches.reduce((sum, b) => sum + b.outputYieldKg * b.bulkCostPerKg, 0);
    const grossProfit = totalRevenue - totalCost;

    const lineData = filteredInvoices
      .slice()
      .sort((a, b) => a.invoiceDate.localeCompare(b.invoiceDate))
      .map((inv) => ({ date: inv.invoiceDate, revenue: inv.totalAmount }));

    return { totalRevenue, totalCost, grossProfit, lineData };
  }, [invoices, productionBatches, from, to]);

  const cartonsReady = finishedCartons.reduce((sum, c) => sum + c.stockQty, 0);
  const cartonsValue = finishedCartons.reduce((sum, c) => sum + c.stockQty * c.costPerCarton, 0);

  const handleInventoryExport = () => {
    exportCSV("inventory.csv",
      ["Name", "Type", "Stock", "Threshold"],
      inventoryData.map((r) => [r.name, r.type, r.stock, r.threshold])
    );
  };
  const handleYieldExport = () => {
    exportCSV("production-yield.csv",
      ["Batch", "Output Yield (kg)", "Wastage (kg)", "Leftover (kg)"],
      yieldData.map((r) => [r.batch, r.outputYield, r.wastage, r.leftover])
    );
  };
  const handlePnlExport = () => {
    exportCSV("pnl.csv",
      ["Date", "Revenue"],
      pnl.lineData.map((r) => [r.date, r.revenue])
    );
  };

  const tooltipStyle = { backgroundColor: "#171717", border: "1px solid #262626", color: "#f5f5f5", borderRadius: 8 };

  return (
    <div className="space-y-6">
      <h1 className="text-xl font-semibold text-[var(--foreground)]">Reports and Analytics</h1>

      <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-end gap-3 rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
        <div>
          <label className="text-xs text-[var(--text-muted)]">From</label>
          <input value={from} onChange={(e) => setFrom(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">To</label>
          <input value={to} onChange={(e) => setTo(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
      </div>

      <div className="flex gap-2 border-b border-[var(--surface-border)]">
        {(["inventory", "yield", "pnl"] as const).map((key) => (
          <button key={key} onClick={() => setTab(key)}
            className={`px-4 py-2 text-sm font-medium border-b-2 capitalize ${
              tab === key ? "border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"
            }`}>
            {key === "yield" ? "Production Yield" : key === "pnl" ? "P and L" : "Inventory Movement"}
          </button>
        ))}
      </div>

      {tab === "inventory" && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button onClick={handleInventoryExport}
              className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
              Export CSV
            </button>
          </div>
          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
            <h2 className="text-sm font-semibold text-[var(--foreground)] mb-4">Stock vs Threshold</h2>
            <ResponsiveContainer width="100%" height={320}>
              <BarChart data={inventoryData} margin={{ top: 5, right: 20, left: 0, bottom: 60 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#262626" />
                <XAxis dataKey="name" tick={{ fill: "#a3a3a3", fontSize: 11 }} angle={-30} textAnchor="end" interval={0} />
                <YAxis tick={{ fill: "#a3a3a3", fontSize: 11 }} />
                <Tooltip contentStyle={tooltipStyle} />
                <Legend wrapperStyle={{ color: "#a3a3a3", paddingTop: 16 }} />
                <Bar dataKey="stock" name="Stock" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                <Bar dataKey="threshold" name="Threshold" fill="#ef4444" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
              <div className="text-xs text-[var(--text-muted)]">Finished Cartons Ready</div>
              <div className="text-2xl font-semibold text-[var(--foreground)] mt-1">{cartonsReady}</div>
            </div>
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
              <div className="text-xs text-[var(--text-muted)]">Finished Stock Value (at cost)</div>
              <div className="text-2xl font-semibold text-[var(--foreground)] mt-1">Rs. {cartonsValue.toLocaleString(undefined, { maximumFractionDigits: 0 })}</div>
            </div>
          </div>
        </div>
      )}

      {tab === "yield" && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button onClick={handleYieldExport}
              className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
              Export CSV
            </button>
          </div>
          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
            <h2 className="text-sm font-semibold text-[var(--foreground)] mb-4">Output Yield, Wastage and Leftover per Batch</h2>
            <ResponsiveContainer width="100%" height={320}>
              <BarChart data={yieldData} margin={{ top: 5, right: 20, left: 0, bottom: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#262626" />
                <XAxis dataKey="batch" tick={{ fill: "#a3a3a3", fontSize: 11 }} />
                <YAxis tick={{ fill: "#a3a3a3", fontSize: 11 }} />
                <Tooltip contentStyle={tooltipStyle} />
                <Legend wrapperStyle={{ color: "#a3a3a3", paddingTop: 8 }} />
                <Bar dataKey="outputYield" name="Output (kg)" fill="#22c55e" radius={[4, 4, 0, 0]} />
                <Bar dataKey="wastage" name="Wastage (kg)" fill="#ef4444" radius={[4, 4, 0, 0]} />
                <Bar dataKey="leftover" name="Leftover (kg)" fill="#f59e0b" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {tab === "pnl" && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button onClick={handlePnlExport}
              className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
              Export CSV
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
              <div className="text-xs text-[var(--text-muted)]">Total Revenue</div>
              <div className="text-2xl font-semibold text-[var(--foreground)] mt-1">Rs. {pnl.totalRevenue.toLocaleString()}</div>
            </div>
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
              <div className="text-xs text-[var(--text-muted)]">Est. Production Cost</div>
              <div className="text-2xl font-semibold text-[var(--foreground)] mt-1">Rs. {pnl.totalCost.toLocaleString(undefined, { maximumFractionDigits: 0 })}</div>
            </div>
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
              <div className="text-xs text-[var(--text-muted)]">Est. Gross Profit</div>
              <div className={`text-2xl font-semibold mt-1 ${pnl.grossProfit >= 0 ? "text-green-400" : "text-red-400"}`}>
                Rs. {pnl.grossProfit.toLocaleString(undefined, { maximumFractionDigits: 0 })}
              </div>
            </div>
          </div>

          {pnl.lineData.length > 0 && (
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
              <h2 className="text-sm font-semibold text-[var(--foreground)] mb-4">Revenue Over Time (selected period)</h2>
              <ResponsiveContainer width="100%" height={280}>
                <LineChart data={pnl.lineData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#262626" />
                  <XAxis dataKey="date" tick={{ fill: "#a3a3a3", fontSize: 11 }} />
                  <YAxis tick={{ fill: "#a3a3a3", fontSize: 11 }} />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Line type="monotone" dataKey="revenue" name="Revenue (Rs.)" stroke="#3b82f6" strokeWidth={2} dot={{ fill: "#3b82f6", r: 4 }} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}

          {pnl.lineData.length === 0 && (
            <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-8 text-center text-[var(--text-faint)] text-sm">
              No invoices in the selected date range.
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { useStore } from "@/lib/store";

const settingsSchema = z.object({
  businessName: z.string().trim().min(2, "Business name required"),
  address: z.string().trim().min(5, "Address required"),
  invoiceFooterText: z.string().trim(),
  defaultProfitMarginPercent: z.coerce.number().min(0, "Cannot be negative"),
  lowStockThresholdDefault: z.coerce.number().min(0, "Cannot be negative"),
});
type SettingsFormValues = z.infer<typeof settingsSchema>;

export default function SettingsPage() {
  const settings = useStore((s) => s.settings);
  const updateSettings = useStore((s) => s.updateSettings);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting, isDirty },
  } = useForm<SettingsFormValues>({
    resolver: zodResolver(settingsSchema),
    defaultValues: settings,
  });

  const onSubmit = async (values: SettingsFormValues) => {
    updateSettings(values);
    toast.success("Settings saved");
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6 max-w-2xl">
      <h1 className="text-xl font-semibold text-[var(--foreground)]">Settings</h1>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
        <h2 className="text-sm font-semibold text-[var(--foreground)]">Business Profile</h2>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Business Name</label>
          <input {...register("businessName")}
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.businessName && <p className="text-xs text-red-400 mt-1">{errors.businessName.message}</p>}
        </div>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Address</label>
          <input {...register("address")}
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.address && <p className="text-xs text-red-400 mt-1">{errors.address.message}</p>}
        </div>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Invoice Footer Text</label>
          <input {...register("invoiceFooterText")}
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
        <h2 className="text-sm font-semibold text-[var(--foreground)]">Defaults</h2>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Default Profit Margin %</label>
          <input {...register("defaultProfitMarginPercent")} type="number" step="any"
            className="mt-1 w-48 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.defaultProfitMarginPercent && <p className="text-xs text-red-400 mt-1">{errors.defaultProfitMarginPercent.message}</p>}
        </div>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Low-Stock Threshold Default</label>
          <input {...register("lowStockThresholdDefault")} type="number"
            className="mt-1 w-48 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.lowStockThresholdDefault && <p className="text-xs text-red-400 mt-1">{errors.lowStockThresholdDefault.message}</p>}
        </div>
      </div>

      <button
        type="submit"
        disabled={isSubmitting || !isDirty}
        className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50"
      >
        {isSubmitting ? "Saving..." : "Save Settings"}
      </button>
    </form>
  );
}

"use client";

import { Fragment, use, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { ChevronDown, ChevronRight } from "lucide-react";
import { useStore } from "@/lib/store";
import { PurchaseReceiptDialog } from "@/components/ui/purchase-receipt-dialog";

export default function SupplierDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const supplier = useStore((s) => s.suppliers.find((sup) => sup.id === id));
  const allReceipts = useStore((s) => s.receipts);
  const receiptLines = useStore((s) => s.receiptLines);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const [expandedReceiptId, setExpandedReceiptId] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  const receipts = useMemo(
    () => allReceipts.filter((r) => r.supplierId === id).sort((a, b) => b.purchaseDate.localeCompare(a.purchaseDate)),
    [allReceipts, id]
  );

  const receiptSummaries = useMemo(() => {
    return receipts.map((r) => {
      const lines = receiptLines.filter((l) => l.receiptId === r.id);
      const totalValue = lines.reduce((sum, l) => sum + l.qty * l.cost, 0);
      return { receipt: r, lines, itemCount: lines.length, totalValue };
    });
  }, [receipts, receiptLines]);

  const totalLifetimeValue = useMemo(
    () => receiptSummaries.reduce((sum, r) => sum + r.totalValue, 0),
    [receiptSummaries]
  );

  if (!supplier) {
    return (
      <div className="space-y-4">
        <NavLink href="/suppliers" className="text-sm text-[var(--text-muted)] hover:underline">&larr; Back to Suppliers</NavLink>
        <p className="text-[var(--text-muted)]">Supplier not found.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <NavLink href="/suppliers" className="hover:underline text-[var(--text-secondary)]">Suppliers</NavLink>{" "}
        / <span className="text-[var(--foreground)]">{supplier.name}</span>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">{supplier.name}</h1>
        <p className="text-sm text-[var(--text-muted)] mt-1">{supplier.phone}</p>
        {supplier.address && <p className="text-sm text-[var(--text-muted)]">{supplier.address}</p>}

        <div className="mt-5 grid grid-cols-2 sm:grid-cols-3 gap-4">
          <div>
            <div className="text-[var(--text-muted)] text-xs">Total Receipts</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{receipts.length}</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Total Lifetime Value</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">Rs. {totalLifetimeValue.toLocaleString()}</div>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Purchase History</h2>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Record Purchase
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium w-8"></th>
              <th className="px-4 py-3 font-medium">Receipt Date</th>
              <th className="px-4 py-3 font-medium">Items</th>
              <th className="px-4 py-3 font-medium">Total Value</th>
            </tr>
          </thead>
          <tbody>
            {receiptSummaries.map(({ receipt, lines, itemCount, totalValue }) => {
              const isExpanded = expandedReceiptId === receipt.id;
              return (
                <Fragment key={receipt.id}>
                  <tr className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => setExpandedReceiptId(isExpanded ? null : receipt.id)}
                        className="text-[var(--text-muted)] hover:text-[var(--foreground)]"
                      >
                        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                      </button>
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{receipt.purchaseDate}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{itemCount} item{itemCount !== 1 ? "s" : ""}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {totalValue.toLocaleString()}</td>
                  </tr>
                  {isExpanded && (
                    <tr className="border-b border-[var(--surface-border)] last:border-0 bg-[var(--background)]">
                      <td></td>
                      <td colSpan={3} className="px-4 py-3">
                        <table className="w-full text-xs">
                          <thead>
                            <tr className="text-left text-[var(--text-muted)]">
                              <th className="pb-2 font-medium">Raw Material</th>
                              <th className="pb-2 font-medium">Quantity</th>
                              <th className="pb-2 font-medium">Cost/Unit</th>
                              <th className="pb-2 font-medium">Total</th>
                            </tr>
                          </thead>
                          <tbody>
                            {lines.map((l) => {
                              const material = rawMaterials.find((m) => m.id === l.rawMaterialId);
                              return (
                                <tr key={l.id} className="border-t border-[var(--surface-border)]">
                                  <td className="py-2 text-[var(--text-secondary)]">
                                    {material ? (
                                      <NavLink href={`/raw-materials/${material.id}`} className="hover:underline text-[var(--foreground)]">{material.name}</NavLink>
                                    ) : "-"}
                                  </td>
                                  <td className="py-2 text-[var(--text-secondary)]">{l.qty} {material?.unit ?? ""}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {l.cost.toLocaleString()}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {(l.qty * l.cost).toLocaleString()}</td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })}
            {receiptSummaries.length === 0 && (
              <tr><td colSpan={4} className="px-4 py-8 text-center text-[var(--text-faint)]">No purchases recorded yet for this supplier.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <PurchaseReceiptDialog open={dialogOpen} onClose={() => setDialogOpen(false)} lockSupplierId={supplier.id} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Supplier } from "@/lib/store";
import { supplierSchema, type SupplierFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function AddSupplierDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const addSupplier = useStore((s) => s.addSupplier);
  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm<SupplierFormValues>({
    resolver: zodResolver(supplierSchema),
    defaultValues: { name: "", phone: "", address: "" },
  });
  if (!open) return null;
  const onSubmit = async (values: SupplierFormValues) => {
    addSupplier(values);
    toast.success(`Supplier "${values.name}" added`);
    reset(); onClose();
  };
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Add Supplier</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Name</label>
            <input {...register("name")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Phone</label>
            <input {...register("phone")} placeholder="0300-1234567"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.phone && <p className="text-xs text-red-400 mt-1">{errors.phone.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Address (optional)</label>
            <input {...register("address")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function SuppliersPage() {
  const suppliers = useStore((s) => s.suppliers);
  const receipts = useStore((s) => s.receipts);
  const [dialogOpen, setDialogOpen] = useState(false);

  type Row = Supplier & { totalPurchases: number; lastPurchaseDate: string };

  const rows = useMemo<Row[]>(() => {
    return suppliers.map((sup) => {
      const supReceipts = receipts.filter((r) => r.supplierId === sup.id);
      const lastPurchaseDate = supReceipts.length > 0
        ? supReceipts.map((r) => r.purchaseDate).sort().reverse()[0]
        : "-";
      return { ...sup, totalPurchases: supReceipts.length, lastPurchaseDate };
    });
  }, [suppliers, receipts]);

  const columns = useMemo<ColumnDef<Row, unknown>[]>(() => [
    {
      accessorKey: "name", header: "Name",
      cell: ({ row }) => <NavLink href={`/suppliers/${row.original.id}`} className="text-[var(--foreground)] hover:underline">{row.original.name}</NavLink>,
    },
    { accessorKey: "phone", header: "Phone" },
    { accessorKey: "totalPurchases", header: "Total Purchases" },
    { accessorKey: "lastPurchaseDate", header: "Last Purchase Date" },
  ], []);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Suppliers</h1>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Add Supplier
        </button>
      </div>
      <SortableTable data={rows} columns={columns} globalFilterPlaceholder="Search suppliers..." />
      <AddSupplierDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

