// /raw-materials/[id] and /raw-materials (row action).
export function PurchaseReceiptDialog({
  open,
  onClose,
  lockSupplierId,
  lockRawMaterialId,
}: {
  open: boolean;
  onClose: () => void;
  lockSupplierId?: string;
  lockRawMaterialId?: string;
}) {
  const suppliers = useStore((s) => s.suppliers);
