  const today = new Date().toISOString().slice(0, 10);

  const [supplierId, setSupplierId] = useState(lockSupplierId ?? suppliers[0]?.id ?? "");
  const [purchaseDate, setPurchaseDate] = useState(today);
  const [rows, setRows] = useState<ItemRow[]>([
