        const isActive = !!item.href && (pathname === item.href || pathname.startsWith(item.href + "/"));
        return <MenuItem key={`${section.title}-${index}`} item={item} isCollapsed={isCollapsed} isActive={isActive} />;
      })}
    </div>
  );
}

